window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_025"]={"n":"洪亮吉","dyn":"清","poems":[{"t":"伊犁纪事诗四十三首 其二十四","f":"七言绝句","c":["黄泥墙北打门频，白发来辞喜气新。","却买鲜鱼饲花鸭，商量明日饯归人。"]},{"t":"伊犁纪事诗四十三首 其八","f":"七言绝句","c":["芒种才过雪不霏，伊犁河外草初肥。","生驹步步行难稳，恐有蛇从鼻观飞。"]},{"t":"晓行","f":"七言律诗","c":["村鸡喔喔酒全倾，拥被求衣事晓行。","四野月明迷向背，一山云出定阴晴。","春残苦乏加餐信，道远愁非负米程。","醉醒十年前事起，马头尘梦较凄清。"]},{"t":"溪南曲","f":"古风","c":["溪西月不华，溪北桃无花。","风光只落溪南路，和月和花筑楼住。","花枝二月人二旬，楼高一层春一分。","溪光已隔画桥影，柳色自斗疏阑春。","岸云凝红水云白，总逊春衫好颜色。","百花开处百禽鸣，楼上添衣楼下行。","寻芳肯到春溪口，堤上行人学垂手。","放船肯过长河湄，墙头女儿仿画眉。","画眉尚避春莺见，照鬓都疑水禽羡。","镜里浓云晓上头，竹中轻粉宵匀面。","春幡亲制初护见，楼角三面悬玲珑。","眸迎深馆迢迢绿，手展文窗扇扇红。","星疏夜久愁犹立，露冷草香虫尚蛰。","百饼薰笼总厌烧，启帷试放生香入。","消息今年异往年，客巢新定故巢迁。","愁边晓泪疑含露，望里春潮已接天。","伤春曾到春台畔，笼鸟生疏茶敢唤。","背客亲移北户镫，呼鬟更掩重门扇。","短短疏篱漠漠尘，沿溪楼阁对墙身。","缘知溪路经三折，只共波光住浃辰。","可怜门左闲亭坞，三月谁为众香主。","抛客年光誓不停，迷人草色寻应苦。","一样扁舟去未还，五湖踪迹异三山。","春来依旧花千树，梦醒空愁月一弯。"]},{"t":"元夕看桃","f":"七言古诗","c":["元夕一年居一方，接天歌吹来咸阳。","终南山月盛光采，一夕楼上铺新黄。","崇仁坊前百戏陈，杂乐共作秦声尊。","颇欣土俗乐丰岁，巷少服马居无人。","严寒初除信风劲，风里试镫镫不定。","端礼门连长乐楼，万声压市嚣难听。","连宵宾从席屡移，选舞彻夜殊忘疲。","屏风高障碧天色，蜡泪满堆红地衣。","园南独客愁争逐，看花欲来深径宿。","避寒三度著春衫，照梦千枝列华烛。","墙头月色清可怜，桃花一枝影入筵。","江南无此早春景，自爱枕上看花眠。","须臾舞寂将残夜，月向城西鹊巢下。","一阵帘前料峭风，远鸡声里寒桃谢。","乡闾此时谁复留，癯崔瘦蒋成俊游。","横塘半里足箫鼓，镫火直接三元楼。","十年两度清游寡，更有汪伦手堪把。","江馆云迷宛转箫，帝城月照流离瓦。"]},{"t":"缥缈岭纳凉","f":"古风","c":["云门古松三十七，三十六株鳞尽裂。","一松蟠蟠径离石，势欲上天犹去尺。","白云移松巅，巨石忽欲走。","岩风吹征衣，上险切星斗。","石镜露落，山泉微光。","暝色入树，松花初黄。","人间残暑不至此，鹤氅乍著宜新凉。","云光深，霞色浅，倒影空濛众山显。","枕泉半日不饮泉，饱向松梢餐露眼。"]},{"t":"戒坛古松歌","f":"古风","c":["沿山西行日光断，一松如龙黑天半。","松根一龙干九龙，欲攫台殿凌虚空。","虬枝北出风力驶，五里亭边落松子。","苍然一顶常宿云，巢鹤不敢呼其群。","枝蟠入石石不知，石窾常见生灵芝。","年深力厚触山破，根断犹穿北山过。","客行破晓即看松，高下楼阁清光中。","南枝迎阳日气浓，北枝腊雪犹未融。","倦时眠松根，醒时看松色。","山僧爱松亦如客，隔岁松花饷人食。","一株旁倚态亦奇，偃盖静觉春阴移。","复有一株云气重，一风微吹干俱动。","其余八九纵复横，倾耳总作龙吟声。","初唐武德至今远，山古寺古涛声平。","我留三宿非爱山，松下百匝偏忘还。","君不见看松如我亦无两，黄海终南各千丈。"]},{"t":"道中作","f":"七言律诗","c":["乱峰高映斜阳赤，谷里人行已深黑。","溪南新月透山来，千朵白云遮不得。","东西秋水隔一村，跣涉尚喜山泉温。","山村树湿昨宵雨，石屋泠泠出蛮语。"]},{"t":"自慧聚寺北行历化阳朝阳观音诸洞晚上极乐峰作","f":"七言古诗","c":["峰形南北殊凹凸，入地上天皆一日。","潜行五里不见天，蜡炬光远空浮烟。","莓苔森森绿疑梦，蝙蝠手扪皆不动。","一风冲出微带腥，足底万窍声俱鸣。","好奇径欲穷颠末，行僮失声炬将灭。","四人急转我后来，风黑恍有千人追。","是时屈指当交酉，出洞见天天尚昼。","饮泉百盏神始清，坐调鼻息方远行。","树巅斜行途转窄，鸦点扑人如雨黑。","东行一洞势较低，一洞复出清泉西。","斜阳沈沈岭头落，客意极疲龛极乐。","下方已黑天顶青，侧帽恐碍当头星。"]},{"t":"涉汉欲至岘首舆丁误入九宫山时日已将暝因小憩而返","f":"七言古诗","c":["山光欲雨江欲晴，云黑复白波微明。","此时击楫涉江去，薄暝始向前山行。","林梢一抹斜阳色，高下山溪一千尺。","云中道士来远迎，语不分明指碑石。","累累林果红一山，倾耳祇觉禽声蛮。","道旁䃰石削如铁，山溜滴沥苔花斑。","沿冈久立怯北风，送客出户闻敲钟。","昏江棱棱水声起，却喜一星明舵尾。"]},{"t":"阿江泛道中","f":"五言律诗","c":["一山途四出，晓日正当头。","好鸟背人立，清泉择地流。","雾归僧阁暗，云出寺门浮。","半晌沿林走，偏忘路阻修。"]},{"t":"重至黔西宿海棠庭院","f":"七言律诗","c":["阑干十二敞银屏，尤喜芳时此再经。","双柳有情垂槛绿，万山如梦压帘青。","花边惆怅寻前约，叶底参差间晓星。","依旧燕莺飞不定，可能重把夜窗扃。"]},{"t":"九峰园感旧","f":"五言律诗","c":["一雨园林足，泉声百道来。","夕阳明螮蝀，高阁暗莓苔。","燕绕横塘楫，鱼窥曲水杯。","古藤应识我，亲见五回开。"]},{"t":"泰山道中 其一","f":"五言古诗","c":["兹山亘东方，郁勃截生气。","虚轮扇风海，空腹入天地。","其高无端倪，一半植空际。","滃滃云出始，袅若丝发细。","俄焉分道骋，寰宇悉衣被。","洪荒迨今日，年代渺谁记。","登封坛数尺，藉以验兴替。","允哉神明区，心精默相契。"]},{"t":"泰山道中 其二","f":"五言古诗","c":["山人渡海来，告我山势尊。","波面日出时，与山相吐吞。","遥看不知山，谓是天有根。","峰棱破空垂，倒挂日月轮。","青冥一气中，高下固不分。","伊谁启鸿濛，当有主者存。","双厓划然开，截作天东门。"]},{"t":"泰山道中 其三","f":"五言古诗","c":["一山戴一山，重戴至谷口。","遵山视重戴，高仅及社首。","方知众高积，拔势乃得陡。","山坳环数郡，元气蒸泽薮。","中虚蕴灵宝，万古谁敢剖。","天阊虽已逼，地轴亦孔厚。","七十二代君，贞符藏北斗。"]},{"t":"泰山道中 其四","f":"五言古诗","c":["山形非徒高，远莫测所届。","沧溟三万里，石脉透海外。","当其势奔腾，显越齐鲁界。","低瞻饶岳渎，并此析支派。","巍巍兼荡荡，克配天体大。","其标难正视，万象怵光怪。","支峰皆整肃，略不涉奇态。","风递沧海涛，山前作清籁。"]},{"t":"泰山道中 其五","f":"五言古诗","c":["三更望兹峰，月出石腹内。","云容方欲展，雷雨已在背。","明明神所宅，乃复遘阴晦。","冰柱十丈长，惊看石厓戴。","居然神斧落，厓半亦奔溃。","回飙搜激电，雪月光迸碎。","遂令登陟客，倏忽迷向背。","清游虽暂阻，未敢遽思退。","终当携松明，绝壁扫芜秽。"]},{"t":"自励 其一","f":"五言古诗","c":["宁作不才木，不愿为桔槔。","桔槔亦何辜，頫仰随汝曹。","杈丫适当时，旋转如风涛。","高原多低枝，感汝汲引劳。","一朝时雨行，弃置眠蓬蒿。"]},{"t":"自励 其二","f":"五言古诗","c":["宁作无知禽，不愿为反舌。","众鸟皆啁啾，反舌声不出。","岂系果无声，无乃事容悦。","依依檐宇下，饮啄安且吉。","何忍视蜀鹃，啼完口流血。"]},{"t":"同邵进士晋涵寻益然大师塔不得","f":"古风","c":["大师裹足蹁跹衣，佛手曾杀千熊罴。","飘然来归竹窗下，野鸟入掌呼晨饥。","浮云白日忽一转，粥鱼声长鬓毛短。","缘床鼠怯剑气腥，隔竹猿窥箭瘢满。","旄头星落白虎倾，亘亘宇宙当消兵。","海滨招鲁岂同调，午日吊屈斯平生。","呜乎男儿生为冤禽死作佛，生忆名山死归骨。","天都成云荡胸热，上升为星下作石。","枯残姓氏何足惜，自与此山同始卒。"]},{"t":"皋陶祠三十韵","f":"古风","c":["黄屋衣裳古，朱轩日月中。","九共谁第一，四岳誉佥同。","大泽思神降，元臣翊运隆。","陈谟归至道，弼教本和衷。","职亦勤虚听，心期辟圣聪。","曰稽符二典，钦若佐司空。","永执刑无赦，群推法至公。","瘖丞初立禁，瞽瞍愿持躬。","瓜削看孤立，蟊强敢内讧。","两朝天屡荐，三杀帝无功。","父子吁谋合，君臣精一通。","神方歆石纽，禅已谢诸冯。","云鸟搜官纪，山龙仰法宫。","趋庭原震肃，网俗自恢洪。","唐传留吁咈，羲篇续旅丰。","勋将十世宥，律本累朝崇。","六蓼亡何忽，萧曹创岂工。","遂令常叙失，已见簿书丛。","汉典频传赦，流民屡致恫。","以威能克爱，惟狱始兴戎。","世系差仟李，家声混伯虫。","甄衰封未续，布起迹犹雄。","礼乐云孙守，坟祠木德终。","荒原余庙貌，古壁绘青红。","揖让熊罴虎，森严松柏桐。","讹方夔一足，业比舜重瞳。","历殿思成续，瞻筵沐古风。","居人留宿火，行客荐新{麦丰}。","气已殊光岳，声还振聩聋。","徘徊有余叹，五百见知穷。"]},{"t":"昭灵宫祈雨词","f":"古风","c":["阜阳水国当河冲，颍汝作会淮作宗。","淝茨涡?柳渒从，六水阔绝流成壅。","二水澒洞声汹汹，导水与水合则{氵众}。","多时狂飙卷老葑，?曳彘尾牛身鳙。","尉官鮇鲔文胥鰅，三足六眼趋郺?。","虾须倒垂尺五浓，张鳞奋沫敢肆纵。","淮神怠职耄且憃，俾鲧治水竟罔庸。","祠官屡沈圭璧琮，帝怒下遣电目瞛。","命截左耳投荒凶，青冥赫焉念鞠讻。","割壤千里颁龙封，龙君甲族匪出崶。","戴以虬角红绡笼，前身作令儒者容。","宫中九男立而升，鱼鳞著身爪缚胸。","龙服被体何雍雍，髯翁守州德望颙。","作碑刻石谬致恭，心知其奇不欲攻。","春享秋享陈鼓钟，琼飧玉饔酒百㼻。","三岁特间一岁豵，云官敬神神惠农。","沙濆浒流俱淙淙，颓猋庉霾?雺?。","神实有术能弥缝，当年辟宫竖楔枞。","越六百载犹崇墉，披图朅来值杪奥。","怪事咄咄欲起讼，无何灵宫鼓逢逢。","神欲索食凭里?，侧闻灾荒惧尤凶。","麦枯而腓树乾?，其雨其雨思灵零。","神纵有食惭{石宁}?，我来龙穴追龙踪。","将巫祝辞里具供，有祷而应斯真龙。"]},{"t":"乌兰乌素道次","f":"七言律诗","c":["乌兰以北地不毛，极视千里无秋毫。","穷荒鸟亦拙生计，啄土饮雪居无巢。","居人觌面能欺客，兽复欺人占居宅。","健儿弯弓射不得，空手归来气填臆。"]},{"t":"重过废园有感","f":"七言律诗","c":["十二窗棂敞绛纱，关心闲看后时花。","残春寥落成秋梦，晓日荒黄似月华。","忆旧已无机上锦，清游思泛斗间槎。","横塘波影空如昔，噪尽官私两部蛙。"]},{"t":"古香斋柏树歌为陈刺史赋","f":"七言古诗","c":["古香斋头两株柏，出土根同干如劈。","主人斋屋斜向东，一树从南一从北。","虬枝击屋屋已破，拔地青苍刺天黑。","森然四角沈阴满，日出当心不能赤。","人间落落古丈夫，天半亭亭挺孤直。","饱经雨露颜仍黝，不与凡姿竞颜色。","主人爱客客奇绝，三十年前住昕夕。","客行握别树始栽，树竟几番长过客。","今来盘薄山斋内，树与主人皆素识。","摩挲抚树对主人，可惜主人头竟白。","客今行周三万里，树亦添高廿余尺。","祁连山头樠木满，曾逊此株雄且特。","顶平不待修雷斧，干老偏能挽风力。","枝经数折撑霄汉，根已三重透泉脉。","因思复有三十年，树欲抉天人入穴。","沈吟不厌百回步，徙倚每闻三叹息。","十围栎树枝皆俯，半里松涛响谁敌。","心空早厌禽巢闹，眼冷静将入海阅。","商量何物伴岁寒，移得园东丈人石。"]},{"t":"自新塘至伍浦溪行杂诗 其一","f":"五言律诗","c":["溪水绿已穷，岩扃忽重闭。","日华与山翠，层叠川上腻。","前村爨烟好，穿此石林细。","一径山雨来，寥寥入秋气。"]},{"t":"自新塘至伍浦溪行杂诗 其二","f":"五言律诗","c":["瓜花黄无端，被此一川绿。","晨凉把竿好，闲坐此溪曲。","人家隔坡水，路暗通石谷。","日午携榼来，人声出山腹。"]},{"t":"自新塘至伍浦溪行杂诗 其三","f":"五言律诗","c":["两村本一村，中有云水界。","溪流经数折，南北已分派。","连宵风色紧，目送去帆快。","人定波有声，神鱼望星拜。"]},{"t":"自新塘至伍浦溪行杂诗 其四","f":"五言律诗","c":["陆行富桑麻，水行富菱芡。","惟兹云水乡，不虞年岁俭。","门前临水路，鹅鸭数堪点。","屈指白露交，秋禾又将敛。"]},{"t":"五鼓自伍浦渡湖至东山","f":"五言律诗","c":["到来青历历，七十二峰巅。","骇浪鱼先拜，惊雷鸟已颠。","水声摇短梦，风色眯长年。","昨夜前山雨，茫茫笠泽烟。"]},{"t":"吴梅村祠题壁","f":"七言律诗","c":["寂寞城南土一丘，野梅零落水云愁。","生无木石填沧海，死有祠堂傍弇州。","同谷七歌才愈老，《秣陵》一曲泪俱流。","兴亡忍话前朝事，江总归来已白头。"]},{"t":"度柯冲岭","f":"五言古诗","c":["屋前童失声，屋后山起立。","尤愁沙石滑，空处不置级。","斜晖初没水，行客势转急。","君看厓上树，迅羽亦不集。","飞腾如猿猱，我仆愧难及。","明星三两颗，天已逼斗笠。","石罅出一门，雷霆复相袭。","时时凉沁体，衣袂宿雨湿。","过岭望九华，凌空向予揖。"]},{"t":"登别峰庵望海忽值风雨","f":"古风","c":["朝曦色染沧溟绿，东望海门如半粟。","沧溟突处天荡摇，顷刻已见西来潮。","象山南头蒜山尾，一舸倒流还数里。","风威不敌潮势狂，吹角北岸停帆樯。","君不见日居万瓦鳞鳞内，眼暗头低殊不耐。","此时怀抱觉暂开，足底隐隐闻惊雷。","天公似把炎蒸洗，东海叱龙龙尽起。","一晌江都电影来，翠屏洲上红三里。"]},{"t":"莫愁湖久憩并谒徐中山王画像","f":"七言律诗","c":["结绮临春事久非，隔坡楼殿尚依稀。","到来海燕栖禅幄，运去山龙黯衮衣。","空馆尚余调鹤地，真王徒剩钓鱼矶。","惟应儿女英雄泪，洒向秋空作雨飞。"]},{"t":"戒子书","f":"古风","c":["九垓之内，人同蛾多。","不自僇力，资生则那。","东邻歌钟，北寺击鼓。","严霜入门，响亦凄楚。","人以为欢，我以为苦。","欲贻子金，我不为盗。","宦而巧取，较盗尤暴。","凿楹有蠹，穿径有萤。","益人神知，照我汗青。","疗贫之术，不出户庭。"]},{"t":"马同槽","f":"古风","c":["声嘈嘈，马腾槽。","火炎炎，龙上天。","去年秉黄钺，今年加九锡。","龙旗十二旒，天子在顷刻。","桃花源，武陵船。","问魏与晋何茫然。"]},{"t":"广武叹","f":"古风","c":["一日哭，留狂名。","百日醉，留酒名。","酒名狂名俱不免，先生能作青白眼。","驱车何茫茫，广武何荒荒。","当时楚与汉，莽莽百战场。","百战场，斜日下。","竖子成名尚堪诧。","扰扰何况牛与马。"]},{"t":"苏门啸","f":"古风","c":["阮生狂耶，稽生傲耶。","先生何人，泠泠啸耶。","咸熙魏耶，咸宁晋耶。","先生何人，冥冥隐耶。"]},{"t":"社稷勋","f":"古风","c":["炎精中烬赤帝死。","祖龙西来作天子。","大开明堂锡弓矢。","谋臣谁，裴与王。","股肱谁，荀与羊。","金符玉册何琅琅。","策勋第一推平阳。","当时曾杀高贵乡。"]},{"t":"作佳传","f":"古风","c":["一丸药，劳侍婢。","千斛米，作传纪。","彼哉谯周及门弟。","三分窃据孙兴曹。","正统那付当途高。","君不见一士已没赖半士。","定论早出习凿齿。"]},{"t":"别驾谣","f":"古风","c":["海沂之康，寔赖王祥。","邦国不空，别驾之功。","呜呼别驾今三公。","惜哉不作徐州终。"]},{"t":"岘山碑","f":"古风","c":["杜公碑，碑书功，高岸为谷谷作陵。","羊公碑，碑堕泪，茫茫泪枯碑不碎。","碑不碎，由民心。","君不见古来贤达皆争名，羊公碑后碑俱泯。","此碑非金亦非石，碑之崇，崇以德。"]},{"t":"飞渡江","f":"古风","c":["前扬帆，后执柁，南人仓皇北人坐。","桡居前，楫居左，岸军愁呼水军卧。","城门开，降帆来，七万骑，全军回。","当时若听王浑指，北兵安得飞至此。"]},{"t":"铜驼叹","f":"古风","c":["立人当立德，择子先择嫡。","宫门老臣三叹息，铜驼会见在荆棘，老奴亦言座可惜。","为官乎，为私乎，此座何不归桃符。"]},{"t":"清谈误","f":"古风","c":["王与谢，挥麈尾。","乐与卫，饶名理。","清谈亹亹从天来，洛中已建单于台。"]},{"t":"雉短短","f":"古风","c":["雉短短，飞来入宫院，欲窃主权欺主闇。","昨日杀龙母，今日杀龙子。","可怜铜驼宫，化作荆与枳。"]},{"t":"金谷谶","f":"七言古诗","c":["红蕤花开置行幕。","一杯两杯缓行乐。","美人头向盘中落。","珠歌翠舞昕斜阳。","珊瑚七尺施作床。","人间梦醒春茫茫。","花枝如烟堕高阁。","散尽黄金恣挥霍。","白首同归讯潘岳。"]},{"t":"中台坼","f":"古风","c":["去年诛韩信，今年醢彭越。","骏珧既首祸，瓘亮亦继没。","南风当国势绝伦，手持天下归先生。","中台星坼日复蚀，先生不言务简默。","金墉城，太后薨。","许昌宫，太子凶。","谁与杀者张司空。"]},{"t":"华亭鹤","f":"古风","c":["华亭鹤，云间哭。","声何悲，悲二陆。","白祫喜谈兵，貉奴宁作督。","机山深，三泖阴，莼鲈千里方扬舲，此时笑杀张季鹰。"]},{"t":"除三害","f":"楚辞体","c":["禾兮芃芃，稷兮翼翼。","父老不乐，仰天太息。","长跪告父老，父老究何苦。","父老不苦长桥之蛟，与南山之猛虎。","父老慎勿悲，山有虎兮虎可摧，水有蛟兮蛟可挥。","儿不读书儿身何为。","儿读书，读书不忘始。","少慕奋身，十年侠士。","长慕事亲，十年孝子。","儿读书，读书不近名。","儿为良臣兮，天王圣明。","儿为忠臣兮，谗人衅成。"]},{"t":"思子台","f":"古风","c":["南风狂，惠风闭，千岁髑髅齿牙利。","承华门，诏谁作，黄门侍郎有潘岳。","许昌宫，逆谁预，黄门将军有孙虑。","思子台，愁云结，许昌一声飞盖裂。","金墉城中贮金屑。"]},{"t":"宁馨儿","f":"古风","c":["宁馨儿，乃贝媚人骨。","少无宦情，皇皇诣阙。","长无宦情，营营三窟。","一代龙门竟谁识，可怜车前拜石勒。","阿堵积室中，持筹亦钱癖，新妇可作阿戎匹。"]},{"t":"侍中血","f":"古风","c":["长安门开鼓声死，贼骑如云走天子。","西来从辇无一人，万乘苍茫草间止。","行间杀气何纷纷，侍中独拜车前尘。","马前飞矢着龙节，侍中独溅衣上血。","侍中血，中散琴，琴声欲绝日欲沉，有子乃不传广陵。"]},{"t":"龙虎争","f":"古风","c":["虎皇皇，北来牵两狼。","南飞值龙龙角张。","洛中硕鼠尺二长。","莫打虎，打虎先伤龙，龙鳞十十五五。","莫打鼠，打鼠已惊犬，犬声欲闻数武。","雄鸡默，雌鸡啼，大马死小马饥。"]},{"t":"十三月","f":"古风","c":["十三月，狼生貙。","十五月，貙生狳。","貙生已难御，狳生奈何许。","蛟龙何况得云雨。","绛灌无文，随陆无武。","以之读书，横览今古。","父作蒙珠离，子作遮须夷。","神州扰扰不可止，洛中又出新天子。"]},{"t":"赤白气","f":"古风","c":["旗猎猎，天门开，云中天子骑龙来。","赤光耀以西，白气耀以东。","非烟非雾，杳不知其蒙蒙。","荧荧煌煌，遂开明堂。","礌礌落落，雄艺卓荦石武乡。","一生低首惟高皇。","幕中乃有张子房。"]},{"t":"特尚可","f":"楚辞体","c":["钟离崩，陷石穴，一如丹，一如漆。","入穴多于虫，出穴莫敢雄。","拔剑刺屋居其中，盐神冉冉兮纷相从。","神之一飞兮九日尽落，浃旬茫茫兮不见城郭。","天空空，野梦梦，遗以青缕，射以雕弓。","盐神去，王廪地。","特与雄，廪君裔。","欲寄食，宁作贼。","官贪如狼政如火，李特尚可尚杀我。"]},{"t":"壮士歌","f":"古风","c":["七尺刀，八尺鞍。","壮士歌，悲陈安。","啾啾唧唧，天阴雨黑。","伏兵邀我西，飞骑追我北。","班骓无声草间匿。","嗟嗟见入不见出。","西流水，东流河。","壮士歌，奈尔何。"]},{"t":"留降款","f":"古风","c":["一千义军守陴哭。","城中天子亦食粥。","谁欤守者索都督。","长安城阙生蒿莱。","长安城门不肯开。","车骑来，万户来。"]},{"t":"中兴瑞","f":"古风","c":["绵绵延延，华光烛天。","正气萃此者，五百二十六年。","时巳过，运乃昌。","朱旗卓地一丈长。","金符落天走建康。","化龙一马兴真王。","龙为王，马遂亡。"]},{"t":"夜半舞","f":"古风","c":["鸡三声，客三唤。","起视东壁有疏灯，启明光已乱。","英雄乘时空浩叹，元明之间久无旦。"]},{"t":"王与马","f":"古风","c":["王与马，共大下。","将军前，丞相亚。","将军无谋丞相诈。","丞相谓将军，三州势堪藉。","事成为王失为霸。","呜呼将军遽叱咤。","鼓频频，肆逆氛。","丞相大义已灭亲。","白旗悬首烦将军。"]},{"t":"新亭泪","f":"古风","c":["慎勿学，楚囚对。","慎勿酒，新亭泪。","天茫茫，天方醉。","人茫茫，人方睡。"]},{"t":"呼伯仁","f":"古风","c":["渡江来，不安坐。","茂伦一言伯仁贺，向见夷吾在江左。","夷吾有急呼伯仁，伯仁百口还理君。","为君沥肝胆，为君全令名。","伯仁言，感天子，夷吾不言伯仁死。","三司耶，令仆耶，知人不易古所嗟。","夷吾亦杀鲍叔牙。"]},{"t":"拜士行","f":"古风","c":["朝亦运百甓，暮亦运百甓。","欲清中原还致力。","古人阴惜寸，今人时掷尺。","欲清中原先惜日。","陶士行，真名臣，神机魏武忠孔明。","陆逊陆抗非其偷，前年击杜韬，今年杀苏峻。","君不见元规枉自受顾命，贼来亦拜陶士行。"]},{"t":"践海水","f":"古风","c":["北风吹海海欲立，海底潜蛟抱冰泣。","马蹄踏海声隆隆，三日不拆玻璃宫。","玻璃平铺三百里，铁骑茫茫践之起。","君不见一声筚篥海水开，海厎已执乖龙回。"]},{"t":"义旗指","f":"古风","c":["去年反王敦，今年反苏峻。","六师束手庾元规，八州观望陶士行。","君父之难安可逃，义旗一指天为高。","官军已成白石垒，贼骑不越朱雀穚。","功成倘忆绝裾处，夜夜精灵泣牛渚。"]},{"t":"献行玺","f":"古风","c":["献行粮，献行玺。","尚薄袁本初，何敢学成李。","二十八宿缠宫门，大业无愧张耳孙。","龙章九锡未八告，白帢八棺还自悼。","还自悼，百六乾坤总群盗，执手传家自忠孝。"]},{"t":"一目主","f":"七言古诗","c":["长安天子眇一目。","长安城中月鼎足。","妖星茫茫射黄屋。","死我者坚活我雄。","东海大鱼化为龙。","男皆为王女为公。"]},{"t":"识英物","f":"古风","c":["儿勿啼，儿啼惊一切。","儿啼何奇，知儿是英物。","儿勿来，儿来光一室。","儿来何殊，知儿有奇骨。","星茫茫，堕儿赖中七。","山岩岩，横儿顶中一。","君不见温太真，擅奇术。","燃犀照余幽魅出，何不携来照英物。"]},{"t":"日书空","f":"古风","c":["夷甫矜空谈，神州已陆沉。","深源复中起，苍生更谁倚。","嗟嗟一百年，处士相后先。","书空计已左，周旋犹作我。","东山捉鼻四十春，苍生所望真斯人。"]},{"t":"海西公","f":"古风","c":["局缩肉，马作犊。","海西公，犊化龙。","犊化龙，是龙子。","朝向离宫生，暮向吴宫死。","吴宫死，悲何如。","君不见，永嘉袖手永昌呼，入庙曾言帝室储。","何因龙种欺黄犊，会见鸡雌扰凤雏。"]},{"t":"鬼董狐","f":"古风","c":["鬼董狐，事何略，天地茫茫总初觉。","元凯谁蟒而攫，元海谁鳞而跃。","敦与温，重笔削。","君不见，枋头既败史笔诬，定论只有鬼董狐。"]},{"t":"东山卧","f":"古风","c":["大谢执如意，小谢挥麈尾。","中谢无所为，泠泠善名理。","一门群从真无惭，闺中飞絮还撒盐。","君不见四十东山卧初足，与人同忧亦同乐，别墅风流赌棋局。"]},{"t":"牛心炙","f":"古风","c":["欲知名，啖牛心，欲书名，聚鹅群。","昔不减阮主簿，今可伍王怀祖。","携诸子，抱弱孙。","婚嫁毕，学尚平。","学尚平，事亦足。","中年以后伤哀乐，得闲且自陶丝竹。"]},{"t":"阿房城","f":"古风","c":["凤凰凤凰止阿房，一雌一雄双翱翔。","不见雀来入燕室，但见浮云闭白日。","凤西飞，雀东飞，肠断朱宫复紫堤。","锦袍一领军前却，凤皇凤皇不如雀。"]},{"t":"长星见","f":"古风","c":["荧惑入南斗，天子下殿走。","荧惑来天垣，天子坐未安。","坐未安，亦何有，长星劝汝一杯酒。","臣愿天子圣列辟，贤追古七十二帝。","恩绵延，臣更左执矢、右执鞭，妖星射落渊厎眠。","陛下圣寿千万年。"]},{"t":"负畚来","f":"古风","c":["负畚来，洛阳鬻。","望尘来，司隶逐。","卿无忘螭蟠，朕无忘龙伏。","嗟嗟景略夺何速。","不事西夷事南服。","八公山，悲苻融。","五将山，毒吴忠。","景略有君死苌手。","景略有儿絷泓首。","丕登先亡镇恶后。","镇恶死，报苻氏。"]},{"t":"行路难","f":"古风","c":["行路难，歌以哭，四座茫茫惨无乐。","松柏何啾啾，屋下尸自愁。","挽歌何慨慷，道上殡自往。","袁山松，愁何工，君家兄弟才偏雄。","呼卢十万掷布帽，卿辈可识袁彦道。"]},{"t":"丁零王","f":"古风","c":["丁零中，一隅地，几人称王几人帝。"]},{"t":"新平寺","f":"七言古诗","c":["长星出天十丈长，东扫宛洛趋雍凉。","明光殿前老父走，甲申乙酉悲鱼羊。","鱼羊食人人更少，长安十陵长秋草。","威凤重飞入禁中，蛟龙更出屯官道。","东帝鲜卑西帝秦，英雄归骨向新平。","苌登自构君臣祸，垂永还操门户兵。"]},{"t":"五经表","f":"古风","c":["宗生去，大事已。","赵生来，大事济。","彼弃龙头附蛇尾。","才何奇，九州小。","书何奇，五经表。","不处城庐处洲岛。","沮渠据北乞伏西。","自郐以下还无讥。"]},{"t":"借鬼兵","f":"楚辞体","c":["城门西，鬼兵十万啾啾啼。","城门东，阴旗猎猎愁磷红。","贼骑欲向南，鬼伯趋䟃?。","贼骑欲向北，啾啾啼鬼伯。","城门开，待鬼来。","椒浆为汝奠，灵甲为汝裁。","一朝贼退归海中，幕府上簿皆鬼功。","鬼兵不来兮奈何许，贼兵皇皇兮矢如雨。","风折兮蝥弧，血染兮头颅。","将军苦身折，天师竟无术。","彼夫人兮真丈夫。","抽刀杀贼贼即呼。","天壤欲似王郎无。"]},{"t":"续佛经","f":"古风","c":["君不见长安天子好禅论，浮屠沙门多以万。","殿陛空陈丰草诗，深宫自进伊蒲饭。","又不见长安天子多武功，蜀氛西靖燕东封。","一朝荧惑星失守，万劫昆明火更红。","可怜德修期愈促，自谓当时邀佛福。","邀佛福，三千佛经盈卧阁，万死难忏姚苌恶。"]},{"t":"槐树赋","f":"楚辞体","c":["槐树赋，述志赋，撰作遐方一何富。","上马能杀贼，下马作露布。","龙吟夜半兴真人，谱系乃出飞将军。","彼夫人兮亦清节，三年不言似亡息。"]},{"t":"虎台谋","f":"古风","c":["兄为囚，妹为虏，父命事仇无不可。","父已死，兄已诛，父命杀仇仇即夫。","父仇不报岂女子，反面事人有余耻。","事已不成宁惜死。","黄泉有血流浩浩，九州之外五经表。"]},{"t":"沐谦刺","f":"古风","c":["一尺七首三尺云，首提革囊飞入秦。","飞入秦，杀龙子，感恩茫茫复中止。","君有疾，吾侍之，君有药，吾奉之。","涔涔泪下不能止，义士今时为君死。","匣中夜半风飕飕，恨不飞斩仇人头。"]},{"t":"彗星出","f":"古风","c":["明堂坐，一龙才升一龙堕。","恸哭来，徐公徐公得无过。","星离离，入太微，经北斗，络紫微。","茫茫一百二十祀，酖君以生不如死。","晋亡亦有死节士。"]},{"t":"义羲号","f":"七言律诗","c":["仇池一隅世忠孝。","宋家日月飞不到。","永初年间义羲号。","当时彤弓与卢矢。","老臣自当臣晋死。","我死善事新天子。","呜呼国亡不与亡。","柴桑处士仇池王。"]},{"t":"桃源记","f":"古风","c":["不闻人声，但闻琴声。","不闻弦声，但闻指声。","桃源中人，羲皇上人。","何论魏人，何论晋人。"]},{"t":"一尺剑","f":"古风","c":["一尺剑，驯两蛇。","五百载，还刘家。","炎精断，典午乱。","真人兴，绍皇汉。","草肃肃，没辇毂。","金之刃之悔不速。"]},{"t":"味卿言","f":"古风","c":["恪谁长，慕容炜，有霍光。","猛谁伍，秦符坚，有仲父。","裕谁堪，司马宗，有曹瞒。","知人何详已何略。","如君之才总谁角，可怜死惭高著作。"]},{"t":"金昌亭","f":"古风","c":["东华吴声犹未已。","司空中书执戈起。","同谋亦闻檀道济。","庐陵何人，武皇爱子陛下弟。","金昌亭边鼓声沸。","磨刀霍霍且及帝。","五蛇升，一龙去。","龙归若得瞻皇驭。","应问尔来何太据。"]},{"t":"东山屐","f":"古风","c":["东山屐，屐不释，屐不释，作山贼。","西堂梦，梦莫论，梦莫论，思王孙。","君才苦多实苦少，别梦盈盈满春草。","君心苦杂迹苦幽，探奇累累山灵愁。","山灵愁，向天诉，桃墟村中夜相捕。","君须成佛骨未仙，生天乃落孟顗前。"]},{"t":"檀江州","f":"古风","c":["可怜白浮鸠，枉杀檀江州。","万里长城君自毁，明年饮马长江水。","长江饮马君有知，目光裂电神骓驰。"]},{"t":"春月畋","f":"古风","c":["咄尔蓑，嗟尔笠。","曷不远昵，我马欲逸。","咄尔骑，嗟尔王。","曷不傍皇，我田欲荒。","一日荒，不得实。","一日饥，不得活。","王将四征营三驱，驱斥老农胡为乎。","还君壶觞不敢食，我田我田食我力。"]},{"t":"封狼胥","f":"古风","c":["朔风一夜长城倒，百万甲兵如电扫。","石头城上烽连天，不见居人见秋草。","秋草秋肥胡马骄，江南地赤总无苗。","雍徐白骨连青冀，又见催书集飞骑。","君不见耕当问奴织问婢，封狼居胥亦何易。"]},{"t":"佛狸谶","f":"古风","c":["江水饮莫饱，佛狸死江岛。","去年岁在寅，今年岁在卯。","崔伯深死亦早。"]},{"t":"宜速断","f":"古风","c":["禁林半夜愁乌号，深宫一举双鸱枭。","鸱枭食母獍食父，假以羽翼授以刀。","斋宫门开烛未灭，举几一挥指齐裂。","湛之不断江湛迟，陛下裁弟难裁儿。","难裁儿，已杀父。","嗟嗟双鸱枭，更假一鹦鹉。"]},{"t":"见要人","f":"古风","c":["衣如鹑，马如狗，道逢八驺不得走。","平生不喜见要人，要人近复生公门。","君不见要人耶亦堪喜，陛下有纶臣仲礼。"]},{"t":"竹林堂","f":"古风","c":["宁馨儿，父不知，渠大齇鼻何如斯。","齇鼻不惧鬼，射鬼鬼杀尔。","今日当屠猪，急付大官厨。","猪来代尔宰天下，竹林堂空鬼亦怕。"]},{"t":"违导旨","f":"古风","c":["欲言耶，负导旨，不言还负翟黑子。","宫中门启戈矛森，臣宁负迹不负心。","天威煌煌距尺咫，臣宁负生不负死。","高渤海，真纯臣，天文书上天颜温。","臣才区区劳奖述，清河司徒臣不及。"]},{"t":"领军腹","f":"古风","c":["七日宴，慎勿开，司空血裹长安台。","牵牛星，慎勿见，苍梧首离仁寿殿。","江州首祸徐州亡，天意总在萧建康。","箙中有箭箭有镞，痛恨不穿领军腹。"]},{"t":"石头城","f":"古风","c":["石头城，悲孝子，悲忠臣，宁为粲死惭渊生。","江陵市，为忠臣，为节士，不作充生作陵死。"]},{"t":"天王家","f":"古风","c":["生不落降王车，死不入天王家。","王敬则虎而翼，板舆迎居别宫耳。","司马家亡亦如此。","王光禄，獭尾哭。","兴亡两见勿复哀，鸾飞又向天边来。"]},{"t":"移吾床","f":"古风","c":["纪僧真，无所须，从官乞作士大夫。","士大夫，非天子命，江家谢家听不听。","欲娶须造中书堂，欲贵须近尚书床。","桃笙三尺床七尺，尚书移床远俗客。"]},{"t":"易犬子","f":"古风","c":["延昌宫中国祚短，神龙堕地化作犬。","杨婆咒祷空纷纷，宁知金翅衔王孙。","王孙忆翁须好作，翁死旬时还奏乐。","花枝袅袅春绵绵，杨郎宫中恣醉眠。","狐裘锦衣左右直，徐郎殿前躬画敕。","宁失官家朝，莫犯周侯刀。","宁违至尊训，莫拒舍人命。","禁中刀敕空纵横，国运讵识归宣城。","尚书不言侍中走，举朝尽醉吴兴酒。"]},{"t":"郎君书","f":"古风","c":["郎君书，悲欲死，不死三军死尺纸。","田横客，走安归，先生血染门生衣。","陆家门生颈已折，袁家门生遭狗啮，先生之灵几时没。"]},{"t":"解散髻","f":"七言古诗","c":["华林园中宴初设，彦回琵琶称第一。","清歌沈季琴王郎，三公解事惟拍张。","尚书尚书技偏乏，稽首臣须用臣法。","臣今有法臣知书，当时封禅推相如。","帝日休哉盛德事，琵琶声停拍声止。","一代风流比谢安，插簪散髻解朝冠。","王郎何似吴兴守，力饮不肯解玺绶。"]},{"t":"八驺叹","f":"古风","c":["君不见邓仲华，二十佐命人争夸。","又不见王仆射，弱冠兴齐推定策。","君名照耀同扶桑，三十官止中书郎。","前无八驺任搥壁，人何轰轰我寂寂。","绛衫戎服官门来，嗟君殊非济世才。","济世才，任轻薄。","驴乎驴乎汝好作，如汝人材皆令仆。"]},{"t":"阅武堂","f":"古风","c":["阅武堂，种杨柳，至尊屠肉妃酤酒。","阿兄来，盘马走，阿丈来，醉一斗。","宫中夜游谁敢毁，宰相巳作破面鬼。"]},{"t":"合肥捷","f":"七言古诗","c":["合肥城边鼓三下，将军乘舆不跨马。","麾幢伞扇沿河堤，兵不贵多还贵寡。","三关关北增高楼，将军闭垒征人愁。","征人谁知法中法，法在用强还用怯。","百战孰比将军功，将军岂数曹景宗。","原头射猎师不竞，行路空歌霍去病。"]},{"t":"谈风月","f":"古风","c":["南尚书，奔竞谪，詹事官求不获北。","尚书选格裁，洛阳令争不回。","停年格，铨选格，羽林夜火尚书宅。","南尚书，北不如，宵来风月谈轩渠。"]},{"t":"山中相","f":"七言律诗","c":["华阳梦破生红尘，山中宰相作外臣。","芒鞋寻山芝草竟，茯苓屡辱官家命。","官家手敕来岩陬，先生不愿金笼头。","同时亦有何处士，将须不得臣老子。"]},{"t":"鹿子开","f":"古风","c":["建康城头众惊走，枨枨取人饲天狗。","朝呼食肉宵呼肝，枨枨得人食始欢。","食始欢，杀鹿子。","龙公不死鹿子死，四十八年王气止。"]},{"t":"房公马","f":"古风","c":["糗盈升，草盈把，儿童竞养房公马。","见公之马还思公，连钱蹀躞奔儿童。","儿童粟多果马腹，更瓣名香马前哭。","马前哭，因思公，君不见房公之马鲍氏骢。"]},{"t":"鲜卑奴","f":"楚辞体","c":["铜拔打铁拔，元家岁将末。","鲜卑奴起渤海东，电隐隐兮雷轰轰。","朱家魏家总非匹，一冒空拳一穿鼻。","贼来百箭杀百人，武牢不死真有神。","宜训宫中叩头列，一母三天亦人杰。"]},{"t":"水东流","f":"古风","c":["欲要君，四十启。","欲争君，二千骑。","东帝不成作西帝。","征途歔欷，悲啼勿啼。","君心有南北，此水无东西。","水东西，犹入海，魏东西，天命改。"]},{"t":"南飞吉","f":"古风","c":["乌鸦耶，燕雀耶，南飞者利耶。","辕门中，置大鼓，将军紫衣气如虎。","弯弓北来射鹦鹉。"]},{"t":"明月谣","f":"古风","c":["明月明月，相随不灭。","昨宵入怀抱，今宵委荒草。"]},{"t":"狐非狐","f":"古风","c":["天门开焦梨，狗子天边来。","狐非狐，貉非貉。","吠声长，达河朔。","青雀何嗷嗷，新巢复旧巢。","旧巢鹦鹉啄，新巢饱犬腹。","犬乎犬乎尔何酷，会见金鸡树头哭。"]},{"t":"金瓯缺","f":"古风","c":["萧绎盲老公，侯景跛老子。","中原龙战四十春，乾坤戾气归斯人。","斯人不来国不破，谁使金瓯向空堕。","当杀不杀慕绍宗，当断不断吴老公。","跛奴之祸祸已酷，盲僧衅成还骨肉。"]},{"t":"臣如龙","f":"古风","c":["天子勿走马，大将军嗔。","大将军，劝陛下酒敢勿闻。","黄门郎，来前且受意，痴人势亦小差。","未欲进食先挥刀，龙耶虎耶亡崇朝。","亡崇朝，反及祸。","臣如龙，北面坐。","臣如虎，尚是可。","臣如鼠，已杀我。"]},{"t":"寒山石","f":"古风","c":["一片石，寒山顶。","余者谁，比蛙黾。","蛙声蚓声犹可识，邢家魏家工作贼。"]},{"t":"百年冤","f":"古风","c":["济南毅魄死不灰，九死上叫天关开。","精诚入日日忽变，白气夹日如长围。","凉风台前血一斗，百年来时绕阶走。","儿今何罪生王家，乞命作奴还俯首。","深宫半玦留分明，儿今已死忍独生。","忍独生，还把玦，明月不来空断绝。","君不见娄家血泪还缠绵，济南悲罢悲百年。"]},{"t":"握槊来","f":"古风","c":["臣弹筝，君进酒。","君持觞，臣为寿。","君王沉醉宫生春，儿家乃有握槊臣。","赵郡痛哭宫门首，臣为国家不为酒。","珠帘终蔽和士开，兖州刺史需君来。","士开生，赵郡死，非常作事有龙子。"]},{"t":"刘桃枝","f":"古风","c":["刘桃枝，信力士，所为如此事。","永安耶，铁笼死。","平秦耶，露车死。","赵郡耶，雀离死。","大明宫里呼家家，肠肥腊满悲琅琊。","桃枝桃枝技还绝，飞向青天斩明月。","刘桃枝，慎勿过。","君如鸺鹠见者祸，呜呼尔首何时堕。"]},{"t":"金叵罗","f":"古风","c":["为丞郎，郎善盗。","金叵罗，在官帽。","为达官，官善温。","胡桃油，献至尊。","为三司，司善刺。","黄金丹，宽一死。","为流囚，囚善柔。","芜菁子，熏两眸。","盲人当国亦识古，官欲杀弟引庆父。","盲人当国还倾朝，官欲杀舅引薄昭。","盲人耶，竟谁恃。","外有和老公，内有女娲氏。"]},{"t":"延年杖","f":"古风","c":["延年杖，南面植。","大司马前为进舄，太师前为设席。","皇帝陛下，北面进爵。","百僚捧匜，三公洗勺。","臣学孙吴，不学孔孟。","群公雍雍，陛下至圣。"]},{"t":"无愁曲","f":"古风","c":["日短短，苦未足。","夜游还秉烛，琵琶弦拨无愁曲。","斗鸡开府鹰仪同，无愁天子欢无穷。","欢无穷，起相和。","杞人莫自忧天堕，女娲宫中捧石坐。"]},{"t":"百升谣","f":"七言古诗","c":["清风园中菜租减，盲老公言百升反。","枣枝十束弓廿张，百升反贝何寻常。","老公言时老母证，官家比来亦大圣。","天亡明月资秦人，中河不事椎层冰。","吁嗟二妃一皇后，敕勒老公知不久。"]},{"t":"杀一围","f":"古风","c":["撮许贼，何能为，官家更劝杀一围。","平阳城头贼锋挫，美人不来城不破。","严兵何纷纷，伐鼓何喧喧，美人一呼官家奔。","官家奔，亦何往。","君不见马上徒膺祎翟荣，车前已作降王长。"]},{"t":"脚杖痕","f":"古风","c":["欲从君，君不可从。","陛下为不孝，孝伯为不忠。","欲为身，身不可避。","堂上有老母，地下有武帝。","天昏昏，谁与伸。","嗟嗟陛下，勿扪脚杖痕。"]},{"t":"景阳楼","f":"古风","c":["楼高高，插天表，玉树一声天下晓。","宫中天子乐事新，一日可敌千万春。","齐军三来周再至，不恃人心恃形势。","宫女烟花狎客笺，送君还上九重天。","噫吁嘻，胭脂井冷何堪辱，此间乐复不思蜀，一曲吴歌酒千斛。"]},{"t":"高凉洗","f":"七言古诗","c":["中原龙战苦不息，兵戈变尽狼虎迹，帝以伦常付巾帼。","江南王气悲销沉，销沉忠义无一人，投袂乃属夫人城。","许家善心亦国士，陈亡不死隋亡死，死时应愧夫人耳。"]},{"t":"阿干歌","f":"楚辞体","c":["莫听阿干歌，阿干心独苦。","棘城西去白兰山，茫茫隔今古。","阿干为弟言，马伤君莫怒。","弟言报阿干，连枝本同父。","阿干歌，悲无穷，阿干有子还思忠。","登高山而望远海，慨异国之朝宗。","阿干歌，歌自悼，阿干有孙还识孝。","报雠不得留雠衣，缚草作雠兮射雠貌。","阿干歌，歌以风，此歌安得流寰中。","君不见宋湘东与梁湘东。"]},{"t":"鱼鳖桥","f":"古风","c":["高句丽，乃是河伯之甥。","赤乌子，精诚贯日日倒戈。","河伯乃遣鱼鳖为填河。","鱼耶鳖耶，今日济我。","犬耶豕耶，昔日饲我。"]},{"t":"鬼鼓喧","f":"古风","c":["银刀霍霍波粼粼，江鱼见水不见人。","与鱼同居识鱼性，刺鱼要伺鱼入定。","鱼一尾，直百钱，得鱼买醉神祠边。","深秋鬼鼓何填填。"]},{"t":"雌雉卜","f":"古风","c":["羽肃肃，飞来手中伏，男王叩头女王祝。","欲得粟，须剖腹。","腹中粟如玉，今年谷大熟。","九层楼中仙乐作，苏毗千秋，阿修罗万福。"]},{"t":"金羊床","f":"古风","c":["阳春有脚不得走，赤帝骑龙作岁首。","蛮王笑拥金羊床，琉璃珊瑚琥珀光。","真珠璎珞垂两裆，七月七日华筵张。","腰银弓，手金戟，橐驼飞来能啖客。"]},{"t":"新罗人","f":"古风","c":["新罗人，新罗人。","新罗山多水复险，终古犹匿秦遗民。","当是避秦竟深入，深入千年作都邑。","武陵太守空惊传，宁知处处皆桃源。","桃源中，共栖歇，他时饮马长城窟，城边犹认秦时月。"]},{"t":"雨为岁","f":"古风","c":["婆罗蠡鼓喧沙堤，绿鱼千头迎客飞。","舟行海中不见海，云是鲸鲵腹中水。","王开北户迎北人，蔗酒既设椰浆陈。","椰浆陈，且高醉，春为年，雨为岁。"]},{"t":"孔雀群","f":"古风","c":["孔雀，孔雀。","头珠悬，尾翠压，朝飞暮飞与人狎。","蛮中不识文禽尊，呼作家鸡与野鸭。","毛霏霏，羽堪衣。","尉犁山北不可栖，雀乎何不东南飞。"]},{"t":"炖煌西","f":"古风","c":["炖煌西，白骨撑。","日月飞不进，鬼火欲与天争青。","朝行暮行不见影，鬼声西来落空井。","魑魅耶，魍魉耶，丛丛细草生枯骸。","枯骸欲歌人欲哭，炖煌之西且裹足。"]},{"t":"日出处","f":"古风","c":["子夷人，不可悉，我家乃在扶桑之东见日出。","日出不识日所归，茫茫渡海寻光辉。","寻光辉，光欲竭，汝家乃在沧溟之西见日没。","日出必有方，日入必有乡。","愿随东升日，东升朝日王。"]},{"t":"送缪公子公俨之江浦兼简孙大渊如三首 其一","f":"七言律诗","c":["相别翻怜相见迟，坐中人影壁间诗。","魂摇青草东风路，梦立黄河远岸时。","病马去来应有恨，秋禽踪迹本难知。","寥寥门闭红尘里，残腊都将浊酒支。"]},{"t":"送缪公子公俨之江浦兼简孙大渊如三首 其二","f":"七言律诗","c":["去去遥山一桁青，愁程先已梦中经。","江南迢递伤情思，公子知交有性灵。","久据灶觚看读易，暂探石阙纪搜铭。","来朝风色东南便，我亦商归大海萍。"]},{"t":"送缪公子公俨之江浦兼简孙大渊如三首 其三","f":"七言律诗","c":["好因鲂鲤答枯鱼，总觉蛩蛩念巨虚。","白日怀人当槛坐，红云羡尔对江居。","身名莫笑中条叟，乡里须乘下泽车。","丙舍一椽松数尺，未妨他日访吾庐。"]},{"t":"送缪公子公俨出都","f":"五言古诗","c":["五岳未陟一，欲归难戒涂。","抚剑送子行，浮云亦南徂。","子有东顾心，恋此巢上乌。","予怀欲南驰，念彼浊水泸。","两地忽易居，一心安得无。","子行过岱宗，为我谨献书。","已办十两屐，愿届神所都。","俯仰六合间，灵气藉发舒。","神乎幸勿哂，东海贱丈夫。"]},{"t":"奉酬缪公子白沙河见怀诗","f":"古风","c":["尔如华亭鹤，不欲识二陆。","解后得识张季鹰，雅志不复矜飞腾。","我如昭邱狐，读书名博物。","茂先可语不识机，亦欲辞归住蓬荜。"]},{"t":"自城北登虞山日晚始抵城西","f":"七言古诗","c":["我从城北来城西，正中日影已渐低。","琴川七道响如箭，日月湖好分东西。","言游虞仲两高卧，冢柏高与浮云齐。","何应尚父亦来此，世去已远愁无稽。","东旺里接太伯冢，一县已判东西姬。","澹台南游亦曾到，吾道东亦嗟宣尼。","奔车我已愧伯夷，抚剑切莫谈要离。","千年遗事若转瞬，海色黯惨山低迷。","人行深竹苦寥寂，怪鹊飞上山坡啼。"]},{"t":"圭峰山","f":"五言律诗","c":["太华三峰外，兹峰亦削成。","空青无雾障，奇秀与云争。","直柏当胸出，初阳贴掌生。","此江清到底，照影亦分明。"]},{"t":"寒食偶成 其一","f":"七言绝句","c":["伊犁河上值清明，东距关门尚百程。","今日万山深处坐，雨花如梦扑帘旌。"]},{"t":"寒食偶成 其二","f":"七言绝句","c":["谁向洋川纪岁华，沿门都已采新茶。","山中春事忙如许，桃李先开半月花。"]},{"t":"寒食偶成 其三","f":"七言绝句","c":["日午山窗睡起迟，东风吹梦入游丝。","愁无一架秋千影，閒煞满庭红杏枝。"]},{"t":"寒食偶成 其四","f":"七言绝句","c":["衰迟未敢说春愁，枨触莺花忆旧游。","只有白云知我意，随风都到海东头。"]},{"t":"天山歌","f":"古风","c":["地脉至此断，天山已包天。","日月何处栖，总挂青松巅。","穷冬棱棱朔风裂，雪复包山没山骨。","峰形积古谁得窥，上有鸿蒙万年雪。","天山之石绿如玉，雪与石光皆染绿。","半空石堕冰忽开，对面居然落飞瀑。","青松岗头鼠陆梁，一一竟欲餐天光。","沿林弱雉飞不起，经月饱啖松花香。","人行山口雪没踪，山腹久已藏春风。","始知灵境迥然异，气候顿与三霄通。","我谓长城不须筑，此险天教限沙漠。","山南山北尔许长，瀚海黄河兹起伏。","他时逐客倘得还，置家亦象祁连山。","控弦纵逊骡骑霍，投笔或似扶风班。","别家近已忘年载，日出沧溟倘家在。","连峰偶一望东南，云气蒙蒙生腹背。","九州我昔历险夷，五岳顶上都标题。","南条北条等闲尔，太乙太室输此奇。","君不见奇钟塞外天奚取，风力史人猛飞举。","一峰缺处补一云，人欲出山云不许。"]},{"t":"下天山口大雪","f":"七言律诗","c":["危峰北去高无际，过岭风声水声异。","鞭鞘拂处险接天，风势吹人欲离地。","千峰万峰迷所向，意外公然欲相抗。","云头直下马亦惊，白玉阑干八千丈。"]},{"t":"伊犁纪事诗四十三首 其十一","f":"七言绝句","c":["毕竟谁驱涧底龙，高低行雨忽无踪。","危厓飞起千年石，压倒南山合抱松。"]},{"t":"伊犁纪事诗 其四","f":"七言律诗","c":["谪出长城不许诗，一看瀚海放歌奇。","伊犁河谷行舟赏，塞外风情醉笔痴。","头枕天山明月睡，神游冰岭雪鸡嬉。","纵横篆隶闻西域，戍百归乡驻足辞。"]},{"t":"十三夜三鼓抵星星峡","f":"古风","c":["天上星，白皑皑。","地上星，黑累累。","星星峡中十五夜，天星地星光激射。","一屋皆支一星罅，须臾天晦地忽明。","地星却比天星青，北斗黯黯鸡初鸣。","声三号，眠户眨。","炎炎火，星星峡。"]},{"t":"度赤金峡","f":"五言古诗","c":["兹山多赤云，石石悉灵异。","冥濛当月午，宝气烛天地。","丹砂亘南北，碧涧分巨细。","绝顶辟石房，玲珑逼天际。","青羊及驯鹊，一一向空睇。","稍南盘一径，石古路如砌。","森森女娲庙，客户竞私祭。","儿童聚乡塾，师出尽儿戏。","黯黯神烛昏，脂车作行计。","回坡何杂沓，足滑沙石腻。","出峡月已高，惊闻鼓声沸。"]},{"t":"廿八日抵巴里坤","f":"五言古诗","c":["南山高瞰城，下复裂深谷。","巉岩千丈堞，排齿入山腹。","晴天飞雪霰，即已没车轴。","阴寒中人深，肩背苦瑟缩。","千里留战地，往往鬼夜哭。","年残风益暴，客至裹重幄。","灯火集一城，宵惊烛光绿。"]},{"t":"出关作","f":"七言绝句","c":["半生踪迹未曾闲，五岳游完鬓乍斑。","却出长城万余里，东西南北尽天山。"]},{"t":"行抵伊犁追忆道中闻见率赋六首","f":"七言律诗","c":["嘉峪关前夕雾收，布隆吉后晓星浮。","马毛作雪明千里，龙气成云暗一州。","冰谷对床声乍噤，火山当户汗仍流。","平生每厌尘环窄，天外如今一举头。"]},{"t":"入嘉峪关","f":"五言古诗","c":["瀚海亦已穷，关门忽高矗。","风沙东南驱，到此势已缩。","侯门余数骑，骏足植如木。","风递管钥声，岩高忽然拓。","城垣金碧丽，始见瓦作屋。","羌回分畛域，中外此枢轴。","晓日上北楼，长城莽遥瞩。","平衢驰若砥，雪岭俯如伏。","天形界西域，地势极南服。","数折向郭东，泉清手堪掬。","尤惭关令尹，来往饷刍收。","驻马官道旁，生还庆僮仆。"]},{"t":"别惠远城二首 其一","f":"五言绝句","c":["下马步出城，百步屡驻脚。","长刀短后衣，未忍即抛却。"]},{"t":"别惠远城二首 其二","f":"五言绝句","c":["逐客纵已归，犹念未归客。","今宵路岐梦，分道向南北。"]},{"t":"伊犁纪事诗四十三首 其二","f":"七言绝句","c":["橐笔频年上玉墀，虎贲三百笑舒迟。","书生亦有伸眉日，独跨长刀万里驰。"]},{"t":"伊犁纪事诗四十三首 其五","f":"七言绝句","c":["熟客先惊问姓名，记曾跃马入咸京。","当时书记疏狂甚，亲屈元戎作骑兵。"]},{"t":"伊犁纪事诗四十三首 其六","f":"七言绝句","c":["谁跨明驼天半回，传呼布鲁特人来。","牛羊十万鞭驱至，三日城西路不开。"]},{"t":"伊犁纪事诗四十三首 其十五","f":"七言绝句","c":["城隅两日霁寒威，韦曲词人尚下帏。","趁得南山风日好，望河楼下踏春归。"]},{"t":"伊犁纪事诗四十三首 其十三","f":"七言绝句","c":["坐来八尺马如龙，演武堂前夹路松。","谪吏一边三十六，尽排长戟壮军容。"]},{"t":"伊犁纪事诗四十三首 其十四","f":"七言绝句","c":["凿得冰梯向北开，阴厓白昼鬼徘徊。","万丛磷火思偷渡，尽附牛羊角上来。"]},{"t":"伊犁纪事诗四十三首 其十八","f":"七言绝句","c":["瓯脱宵寒忽异常，行辕门外橐它僵。","堂期纵过天中节，明日仍冠骨种羊。"]},{"t":"伊犁纪事诗四十三首 其二十一","f":"七言绝句","c":["城西连日雨昏黄，急溜先倾羊马墙。","夜半老兵惊起叫，皂雕如虎扑人忙。"]},{"t":"伊犁纪事诗四十三首 其二十三","f":"七言绝句","c":["将军昨日射黄羊，亲为番王进一汤。","百手尽从空里举，更凭通事贡真香。"]},{"t":"伊犁纪事诗四十三首 其二十五","f":"七言绝句","c":["伏流百尺水潺湲，地势斜冲北斗垣。","高出长安一千里，故应雷雨在平原。"]},{"t":"伊犁纪事诗四十三首 其十","f":"七言绝句","c":["五月天山雪水来，城门桥下响如雷。","南衢北巷零星甚，却倩河流界画开。"]},{"t":"伊犁纪事诗四十三首 其四十","f":"七言绝句","c":["结客城南缓步回，水云宽处浪如雷。","昨宵一雨浑河长，十万鱼皆拥甲来。"]},{"t":"伊犁纪事诗四十三首 其一","f":"七言绝句","c":["城西乞得暂勾留，何止逃喧亦避仇。","只觉医方有奇效，闭门先学陆忠州。"]},{"t":"伊犁纪事诗四十三首 其三","f":"七言绝句","c":["环碧轩中祟不迷，仅余风柝雨凄凄。","固知此老迂难近，绝胜宵分咒准提。"]},{"t":"伊犁纪事诗四十三首 其四","f":"七言绝句","c":["到日先传领督催，无端堂帖复追回。","间心检点流人册，枨触西川御史台。"]},{"t":"伊犁纪事诗四十三首 其七","f":"七言绝句","c":["古庙东西辟广场，雪消齐露粉红墙。","风光谷雨尤奇丽，苹果花开雀舌香。"]},{"t":"伊犁纪事诗四十三首 其九","f":"七言绝句","c":["鹁鸪啼处却东风，宛与江南气候同。","杏子乍青桑椹紫，家家树上有黄童。"]},{"t":"伊犁纪事诗四十三首 其十二","f":"七言绝句","c":["日日冲泥扫落苔，一条春巷八门开。","外台自有萧闲法，携具方家说饼来。"]},{"t":"伊犁纪事诗四十三首 其十六","f":"七言绝句","c":["幽绝城西半亩宫，古垣迤北尽长松。","危楼不用枯僧上，罔两时时代打钟。"]},{"t":"伊犁纪事诗四十三首 其十七","f":"七言绝句","c":["百辈都推食品工，剪蔬饶复有乡风。","铜盘炙得花猪好，端正仍如路侍中。"]},{"t":"伊犁纪事诗四十三首 其十九","f":"七言绝句","c":["游蜂蛱蝶竞寻芳，花事初红菜甲黄。","只有塞垣春燕苦，一生不及见雕梁。"]},{"t":"伊犁纪事诗四十三首 其二十","f":"七言绝句","c":["一卷平台纪事功，十年循吏说宏农。","便同海外奇书读，腹痛还思邴曼容。"]},{"t":"伊犁纪事诗四十三首 其二十二","f":"七言绝句","c":["万死方来西海头，别司锁钥领兜牟。","关中老守疏狂甚，尚忆东风燕子楼。"]},{"t":"伊犁纪事诗四十三首 其二十六","f":"七言绝句","c":["生羌一月病弥留，夜半魂归户不收。","忽变驴鸣出门去，郭桥何似板桥头。"]},{"t":"伊犁纪事诗四十三首 其二十七","f":"七言绝句","c":["偶选龙媒贡上方，万蹄如铁剖河梁。","驿骝尽解如人立，环拱将军下角场。"]},{"t":"伊犁纪事诗四十三首 其二十八","f":"七言绝句","c":["鹑鸪啼处却东风，宛与江南气候同。","杏子乍青桑葚紫，家家树上有黄童。"]},{"t":"伊犁纪事诗四十三首 其二十九","f":"七言绝句","c":["累臣百计遣秋光，学圃年来寖有方。","莳得菊花三百本，归家亭子宴重阳。"]},{"t":"伊犁纪事诗四十三首 其三十","f":"七言绝句","c":["穷荒连月有恩纶，边雨初晴塞草春。","昨午北郊迎诏使，分明捧日两黄人。"]},{"t":"伊犁纪事诗四十三首 其三十一","f":"七言绝句","c":["怪风时起扑灯蛾，旧燕巢欹鼠作窠。","蒸得春蚊大如斗，南山湿雾入帘多。"]},{"t":"伊犁纪事诗四十三首 其三十二","f":"七言绝句","c":["老饕到此已无缘，且减常餐汲井泉。","十日斋厨冷于寺，故应蔬味胜腥膻。"]},{"t":"伊犁纪事诗四十三首 其三十三","f":"七言绝句","c":["达板偷从宵半过，筝琵丝竹响偏多。","不知百丈冰山底，谁制齐梁子夜歌。"]},{"t":"伊犁纪事诗四十三首 其三十四","f":"七言绝句","c":["篱豆花红藓叶班，时时约客话更阑。","斋厨百品多尝遍，惜少山雌入食单。"]},{"t":"伊犁纪事诗四十三首 其三十五","f":"七言绝句","c":["山沟六月晓霞蒸，百果皆从筵上升。","买得塔园瓜五色，温都斯坦玉盘承。"]},{"t":"伊犁纪事诗四十三首 其三十六","f":"七言绝句","c":["偶向尊前学楚歌，天涯谁识故人多。","郎官湖水清如镜，绝忆三更放棹过。"]},{"t":"伊犁纪事诗四十三首 其三十八","f":"七言绝句","c":["戟门东去水潺湲，山色周遭柳作垣。","日昃马行三十里，纳凉须驻会芳园。"]},{"t":"伊犁纪事诗四十三首 其三十九","f":"七言绝句","c":["待得城楼月欲升，竟携茶具就书灯。","九朝旧事无人听，只有西厅老郡丞。"]},{"t":"伊犁纪事诗四十三首 其四十一","f":"七言绝句","c":["一旬蝴蝶已成团，便拟开筵宴谪官。","携得百花洲畔法，种来鹭粟大如盘。"]},{"t":"伊犁纪事诗四十三首 其四十二","f":"七言绝句","c":["积雨冥蒙路不开，巑岏历尽始三台。","万松怪底都相识，曾向童年入梦来。"]},{"t":"伊犁纪事诗四十三首 其四十三","f":"七言绝句","c":["雪深才出玉门关，三月君恩已赐环。","嬴得番回道旁看，争传李白夜郎还。"]},{"t":"廿九日发古城巡抚伊江阿大令阮曙并马送至水磨合茶话乃别","f":"五言古诗","c":["出城闻泉声，到合复数里。","逶迤冈四面，云向水中起。","蒙蒙萍藻绿，水鸟浴未已。","曲处响始奔，惊流出潭底。","人栽沙果好，都入北窗里。","板屋止两层，高瞻忽迢递。","殷勤相送客，门外尚余几。","挥马去不停，林长久延企。"]},{"t":"除夕巴里坤客帐祀先","f":"五言律诗","c":["昔日公孙瓒，临岐祀北邙。","潸然感先德，忘却在殊乡。","烛借穹庐火，牲求牧泽羊。","荒寒一瓯雪，聊抵奠椒浆。"]},{"t":"夜抵木垒河","f":"七言律诗","c":["到得山村夜已迷，窗棂全不辨东西。","狼驯似马凭鞭策，鹊大于鸡共树栖。","穴鼠岸然欺客睡，蛮猿时复杂儿啼。","峰峰塞路谁能究，只觉檐前北斗低。"]},{"t":"三台夜宿","f":"七言律诗","c":["峰峦南北途千曲，天半乱霞烘马足。","山程九十到未迟，觅得山村最西屋。","绿莎窗开波影摇，酒渴我尚餐山桃。","夜阑残月仅一线，紫燕白鸽争归巢。"]},{"t":"宿沙枣泉","f":"五言古诗","c":["伊犁三月三，哈密六月六。","风日固自佳，其奈客幽独。","今宵宿沙枣，马病扰心曲。","挥扇急出门，临流看飞瀑。","林长久延伫，石喜可容足。","鸦巢厌人影，月出景相逐。","双燕更有情，更残导归宿。"]},{"t":"四十里井汛","f":"五言古诗","c":["四十里井间，只有十家住。","十家汲井过，并向麦畦注。","麦肥如野菽，饱食耐征戍。","耕余了无事，间或插桑苎。","遂令半里间，夹屋无杂树。","南山团作障，三里塞去路。","时有归墟人，穿云如白鹭。"]},{"t":"初八日乘月行四十里至三个泉宿","f":"七言律诗","c":["人烟百里何渺茫，疲裸独行古战场。","高天下地总一色，明月白雪分清光。","拂眉时有山禽过，清献声高野禽和。","三泉屈指尚半程，我倦欲从云外卧。"]},{"t":"长流水题壁","f":"古风","c":["短流头，长流头，长流水，流不休。","黄芦关，格子墩，二百里，无军屯。","黄尘烧，赤日炙，声如雷，裂山石。"]},{"t":"抵哈密日诚毅伯伍弥乌逊招饭署东蔬香圃","f":"五言古诗","c":["屋中书绕屋，堂下水周堂。","清绝无余事，时闻薜荔香。","昔闻东陵侯，今见安山伯。","皆种五色瓜，偏能饷行客。","蔬圃虽一隅，百种花皆具。","成团蝴蝶来，成团蝴蝶去。","相公真荩臣，司马习边事。","哈密吐鲁番，十年劳卧治。"]},{"t":"自哈密至苦水铺作","f":"古风","c":["两车一马装亦华，后乘满载敦煌瓜。","一旬戈壁苦无食，幸与瓜时适相值。","日昨长流河，今日苦水泉。","不复置茗椀，惟应进瓜盘。","两旬遥遥入关口，纵剩数瓜当亦朽，即以车藏酒泉酒。"]},{"t":"自三堡至头堡一路见割者不绝多回部所种","f":"古风","c":["三堡至头堡，亩亩麦新刈。","咸携菠笨车，往返数难记。","……“缠头”何辛勤，风雨所不避。","全家拿筐盛，儿女在旁戏。","一岁只一收，仓箱已云备。","……今看戈壁外，活壤庶无弃。"]},{"t":"咏史篇","f":"古风","c":["运去矣，籍若何，八千人散汉一歌。","时至矣，胜亦武，百二关亡楚三户。","噫吁嘻，秦明月，汉大风，恨有竖子无英雄。"]},{"t":"初三","f":"五言律诗","c":["初三花发槛，初五月窥门。","楼小难藏影，帘重不隔魂。","蛛丝黏镜湿，鼠泪滴灯昏。","笛忆参差响，书摩宛转痕。"]},{"t":"破晓","f":"五言律诗","c":["破晓帘前望，园荒绿欲齐。","春知来路阔，天觉过墙低。","惊笋有时折，野莺无数啼。","萋萋一坡草，踏尔过桥西。"]},{"t":"中井乡歌为邹翁赋","f":"古风","c":["山花只入房，山燕只栖梁。","一春绿竹不过墙，一生游鱼不出塘。","谁来丈人家，北郭瘦李西溪杨。","谁和丈人诗，南巷狂沈东头王。","丈人十双田，岁得千斛粮。","丈人一陂泽，岁牧千尾羊。","嫁女不插花，娶妇但识桑。","人间有此太古方，丈人不出中井乡。"]},{"t":"午睡","f":"七言绝句","c":["一树藤花六尺床，饧箫声远绕空墙。","幽眠乍起浑无事，新月在天春昼长。"]},{"t":"题阿房宫图","f":"古风","c":["一百万卒长城中，四十万卒新安东。","咸阳闾左已尽发，余者内筑阿房宫。","小刑鞭笞大刑族，趣就咸阳万间屋。","连城跨渭百里余，日月光穷许然烛。","秦家筑城非一隅，秦家筑宫连百区。","雄心一世至万世，束缚黔首常安居。","可怜绢粉今凄瑟，焦土星星野萤出。","版屋祠荒赛百虫，阿房赋冷吟残虱。","噫吁嘻，悯儒乡，火一日。","咸阳宫，火三月。","君不见，楚人灰红秦烬黑，汉家龙兴由火德。"]},{"t":"芳茂山夜宿","f":"七言律诗","c":["节物无端五月前，喧声彻夜扰幽眠。","雷穿石壁都成窟，雨挟溪鱼欲上天。","深洞三时寒地气，断山十里接人烟。","清闲不复营余事，静把《元经》晓夕研。"]},{"t":"园居","f":"五言律诗","c":["十里巢营树，春深客到初。","上楼人影瘦，灭烛雨声疏。","隔岁书犹读，齐年发共梳。","庾郎贫正甚，同此食园蔬。"]},{"t":"小池春涨","f":"五言绝句","c":["昨宵惊波来，漂去所著屐。","下床方欲索，摸得一双鲫。"]},{"t":"独酌谣四首 其一","f":"古风","c":["独酌谣，独酌无所好。","生来菖蒲花，不解向人笑。","阿三为我提壶，阿二而我行沽。","风吹门开，蝴蝶自来。","挥之不去，落我酒杯。","一杯邀春风，一杯待明月。","哜哜嘈嘈声不歇，市上人催酒钱切。"]},{"t":"独酌谣四首 其二","f":"古风","c":["独酌谣，独酌无所知。","离离春心开，飘飘若游丝。","山风为我披襟，百舍为我行吟。","楼高三层，月不得升。","燐火飞出，光明若灯。","上楼钟声三，下楼鼓声四。","冥冥濛濛飞雨至，蝙蝠吓人还展翅。"]},{"t":"独酌谣四首 其三","f":"古风","c":["独酌谣，独酌无所忧。","天边开八地，地上列九州。","三江昨饷鯸鲐，百粤复馈离支。","何曾开筵，日食万钱。","边令之腹，无其便便。","一石亦不多，一斗亦可已。","琳琳琅琅乐声起，劝客高眠洞房里。"]},{"t":"独酌谣四首 其四","f":"古风","c":["独酌谣，独酌无所待。","刘伶及杜康，倏忽渺千载。","北斗为我持杓，列宿为我餔糟。","花开如盘，劝客尽欢。","出饮世上，万人围观。","牛医既可招，狗屠亦难舍。","朝朝夜夜心自写，狂药醉人无死者。"]},{"t":"双船行","f":"古风","c":["侬家住横山，生长山桥东。","昨日出赛神，忘却拜社公。","来时船头雨，去时船头风。","侬家住云溪，生小绣古佛。","归宁无一程，返棹不终日。","来时半帆风，去时半帆月。","双船遥遥何处分，出得小溪当水门。","姊行持香妹持烛，同向晏公祠内祝。"]},{"t":"行云","f":"古风","c":["行云欲升天，流泉欲注地。","同焉出一山，由来心迹异。","高高下下一日中，水气转绿云光红。","朝云升天暮归岭，只有流泉去无影。","君不见，作霖他日遍九州，努力倘逢东海头。"]},{"t":"汪生彦和出元人画二十幅分赋其五 其一 留侯归汉图","f":"古风","c":["君不见，竹冠布衣位至尊，汉家丞相非高门。","骊山罪徒满阙下，黥面盗首王皆真。","当时入关佐天子，三杰首数韩王孙。","留侯儒者固益上，讵能刀笔同时论。","秦凶竟从赵高匿，楚虐幸有项伯恩。","英雄归汉有本末，丹青照水颜疑神。","平生折节黄石公，我怀独有沧海君。","咸阳原争两竖子，冥冥者鸿竟离群。","始知高视出一世，四皓未免趋风尘。","留侯功成即乞身，心所师者真其人，赤松黄石何足云。"]},{"t":"汪生彦和出元人画二十幅分赋其五 其二 伏生授书图","f":"七言古诗","c":["汉家龙兴及三世，高论六籍搜根株。","济南硕儒老犹在，遐算未断神疑输。","谁何作图貌奇古，牙齿剥落身须扶。","当时秦王厌章句，生也幸得逃其诛。","乾坤非常炙燔祸，灰烬尚欲生真儒。","峨峨执经门大夫，太常子弟秀者储。","《尚书大传》世有本，乃谓口授劳呫嚅。","千年此论出安国，更以隶佐亡蝌书。","我怀不以紫夺朱，兀兀起坐重披图。","还怜真本生已易，断篇何止将蒲姑。"]},{"t":"汪生彦和出元人画二十幅分赋其五 其三 季布任侠图","f":"古风","c":["君不见，辒凉夜半离法宫，豪杰扰扰黄尘中。","原尝春陵有家法，杀人乱世非英雄。","谁何要间佩两龙，短裘骏马羞雷同。","报仇结客尽一世，末路顾与曹邱通。","我怀嗤此田舍翁，兀兀一饮还千钟。","呜呼男儿不种东陵瓜，有酒亦浇剧孟家。","勋名生在死即尽，姓氏肯使余人夸。","披图怜君钟然诺，广柳车来容束缚。","一生幸免两头虫，令人千载悲丁公。"]},{"t":"汪生彦和出元人画二十幅分赋其五 其四 张苍治历图","f":"七言古诗","c":["挈壶失官晦朔忙，闰位不复归明堂。","专家历象弃灰烬，日角月齿凭荒唐。","伊谁守官柱下史，兀兀不语悲张苍。","缘知灭水复不久，早奉定历归兴王。","披图黍米绘极细，如汇六历分低昂。","百年星纪互得失，谭天口屈犹能张。","扶风著书首《尧典》，禆昼益夜差五商。","铜壶箭复减高密，迫促日驭无辉光。","我从太初引之长，稍减阴历还归阳。","谁推北辰定天纪，复需南正司总章。","天人当日理本一，古几至德来洪荒。","君官柱下得几载，闻见犹胜洛下黄。","何人更论五德定，汉兴可以追轩皇。"]},{"t":"汪生彦和出元人画二十幅分赋其五 其五 贾谊上书图","f":"古风","c":["洛阳少年真可喜，长沙上书思治安。","致君尧舜固盛事，不问宰相皆材官。","霸陵思治让复再，德薄何能四三代。","此时一官次邓通，憔悴日值甘泉宫。","无端鸮凤引作侣，坐使谮谪来南中。","君不见，南中还留屈原宅，千古万古伤卑湿。","斜阳何必鵩鸟飞，吊古宁同楚囚泣。","孝文重道不重儒，孝武重儒谁上书？","可怜牧豕亦作相，殿上挟策羞吾徒。","如公季命关世数，经术宁同太常错。","卷图不忍见横流，中有沉湘一篇赋。"]},{"t":"对月","f":"七言律诗","c":["铜铺蚀月月不流，晓星对户如凝眸。","此时灯影薄于纸，金鸭炉中瑞烟死。","东家西家蒙蝴蝶，孤客夜长闻落叶。","何当反影入潭底，唤起老龙吟海水。"]},{"t":"青山谒太白墓","f":"古风","c":["骑鲸醉月不肯留，死后却葬青山头。","青山无人几千载，薜月松风苦相待。","我欲发语惊鸿蒙，诗成还输白也工。","笑谓先生安得死，明星在天月在水。","直须痛饮齐悲欢，大地何似杯中宽。","调羹著袍未必喜，知公不死长安市。","夜郎去去愁瘴烟，知公不死南荒天。","公乎公乎死亦达，不见世人皆欲杀。","胸罗文字不博餐，下笔神鬼谁解看。","公乎坎壈有若是，我辈自合号饥寒。","君不见，杜陵叟亦太寂寞，死葬骚乡掩诗魄。","耒阳属甫此属君，不信名山会成错。","临江略试犀角然，水族不足穷奇观。","此间地下真五色，谢眺文章谪仙笔。","汤汤日夜流无穷，当年尔去波涛中。","波涛澒洞一千丈，怯尔文澜不能上。","噫吁嘻，沧桑陵谷今古愁，太白入月西江流。","安知千秋而万岁，浮者不沉沉者浮。","君不见，江流逼岸无三里，会见青山没红底。","一杯酬尔倘有灵，捉月仍从水中起。"]},{"t":"杂诗 其一","f":"五言古诗","c":["黄云如车轮，吹堕郭北门。","霜蹄与短毂，碾作十丈尘。","尘飞值浮云，莫遏东归心。","东归亦何意，咫尺愿作霖。","作霖会相保，栖汝在弱草。"]},{"t":"杂诗 其二","f":"五言律诗","c":["浮萍从东流，桃梗从西浮。","两心苟不渝，终会大海头。","所苦对面间，有若万里修。","爱君屋上乌，弹君林中鸠。"]},{"t":"古桧行","f":"七言古诗","c":["城头古树记以百，非宋非元李唐植。","森森古桧蟠空苍，奇气矫作百夫特。","黄昏过树雷雨青，白昼拿人爪牙黑。","眼经百岁若飞电，身阅四朝犹过客。","霜磨雨洗遗迹尽，剩有创瘢余径尺。","子城峨峨树历历，建炎年中恶氛逼。","一呼落日兵四登，百战孤云气逾直。","将军白马当树立，砍剑剑摧砍刀涩。","风云此日总削平，穴腹犹容怪蛇蛰。","主人爱树识树性，不遣虬枝两相击。","南枝使南北使北，以松归松柏归柏。","树老枝柯总有神，时清冰雪皆生色。","余生好奇奇不屈，陡然见之意亦嚇。","摩挲抚树三叹息，此树心空寿金石。"]},{"t":"斗鸡行","f":"古风","c":["灌园老人食无谷，家留一鸡啄人粟。","呼儿饲鸡鸡苦饱，饱食鸡飞儿受扑。","灌园老人住无屋，秋雨穿墙漏床足。","墙倾日引邻鸡来，矮屋疏篱看争逐。","家鸡飞鸣羽肃肃，采不外驰精在目。","邻鸡据地有死心，阴血四周冠怒束。","微生偶然亦当局，顾祸翻怜杀机伏。","屋上啼鸠看欲痴，草间蝼蚁骄难捉。","家鸡飞鸣众鸡怒，归引群雌更呼族。","雄来成队雌挈尾，争磔鸡毛洞鸡腹。","人生快意纵一观，宁知强者弱之肉。","老人呼儿掩蓬户，双泪阶前抱鸡哭。","得失应知感塞翁，安危何事看蛮触。","君不见，屋外连村菜甲黄，年来鸡啄菜多荒。","衰龄尔亦忘机好，卧看青山下夕阳。"]},{"t":"元夕词寄里中诸子 其一","f":"七言绝句","c":["两条门巷对溪流，百舌春来噪不休。","划断云溪春一曲，蒋家明月赵家楼。"]},{"t":"元夕词寄里中诸子 其二","f":"七言绝句","c":["路入杨园春正赊，风光多被女墙遮。","一条芳草王孙巷，绿到桥南是董家。"]},{"t":"太平使院，分赋园中草木四首 其一 古柏","f":"五言古诗","c":["不知何年树，寻根不能到。","枝低独鹘借，心空百虫闹。","物性谋安居，催君路旁倒。"]},{"t":"太平使院，分赋园中草木四首 其二 斑竹","f":"五言古诗","c":["春来爆竹声，灾及松与竹。","宁知枝柯上，斑斑总成玉。","莫待春雷鸣，龙孙先徙族。"]},{"t":"太平使院，分赋园中草木四首 其三 荠菜","f":"五言古诗","c":["食荠味苦酸，食藿饥苦并。","青青一畦菜，味与萝卜永。","愁看三月三，挑残不留影。"]},{"t":"太平使院，分赋园中草木四首 其四 池草","f":"五言古诗","c":["离离千百种，种种出池沼。","深知造化心，无名尔偏好。","一与春风缘，还应作小草。"]},{"t":"春日","f":"七言律诗","c":["白日看云坐小斋，闲无一事入幽怀。","林禽告我春无恙，小树依人影亦佳。","病酒心情愁柏叶，看花消息到芒鞋。","离居一倍风光好，闲煞城南十字街。"]},{"t":"墙上蒿","f":"古风","c":["墙上蒿，一旬高一尺。","回身视根株，知君不能直。","墙上蒿，三春独绵延。","若非年命促，那不愁刺天。","墙上蒿，结根当白日。","宁待霜与霰，节枯由触热。","墙上蒿，乃界东西邻。","成阴苦无多，两处欲市恩。"]},{"t":"当涂道中二首 其一","f":"五言古诗","c":["稍稍雨洒尘，微微转春气。","平原三月中，秾花艳天地。","闲云翳东至，春空亦微腻。","游蜂与蛱蝶，后时识真意。","所居异乡国，微觉风土异。","郊原计尺寸，物力多所弃。","遥遥东归心，欣看麦成穗。"]},{"t":"当涂道中二首 其二","f":"五言古诗","c":["日出庐井喧，流光照虚晨。","山田极柔桑，尚有无衣人。","孩提率牵袂，苦语出性真。","我哀道旁辞，感激为重陈。","造物息百年，未补一日贫。","惨舒各殊抱，何以归真醇。","桑榆苟堪耕，此辈非游民。"]},{"t":"山坑","f":"七言律诗","c":["山根竹鸡啼向晨，催客远梦辞风尘。","柔桑翳村出朝日，春水对户思幽人。","山川西来忽平旷，锦石都随乱流漾。","三家飞雨屋上鸣，四月桃花谷边放。"]},{"t":"雷津","f":"七言律诗","c":["东行出险常左顾，如梦溪山忽无路。","炎天径有黄叶飞，春水人知白鱼数。","薜萝深门带湿开，似讶空谷喧惊雷。","山深往往厌车马，日午谁看官长来。"]},{"t":"夜起登蓬莱岛看日出不见","f":"五言古诗","c":["成此独往心，孤猿屡窥户。","闻钟念初觉，出寺仅数武。","沉沉壑光断，荒荒白云阻。","昏晦持一灯，幽林变溽暑。","流星掌边下，宿羽岩际数。","朝霞信清华，残魄虚卓午。","坡回屡心掉，峰中始轩举。","荡此衣袂云，还成吴会雨。","沿䡮草抽蔓，绝壑风振绪。","亦感筋力疲，孤筇设迎拒。","谁行深谷中，泠泠出疏语。"]},{"t":"黄山松歌和黄二","f":"七言古诗","c":["呜呼哲匠不可逢，拥肿拳曲无舂容。","乾坤一气转巽艮，斯石为石松为松。","松华不承霜雪余，石妙欲出肤腴中。","中臧元气蕴雷电，火土木石皆从同。","神祇千年爱护一，介则集古剥则凶。","吁嗟灵境与世异，太古本遣丸泥封。","地灵药物溢丹井，帝悯黎庶遭鞠讻。","中横巨石忽裂一，精液已漏无由缝。","卑枝无言入樵斧，合干已破缠交踪。","流传世人不解爱，讵有苍翠蟠心胸。","裁枝屈盆恣糅矫，辇石㔉骨工磨砻。","山川一朝物性失，光怪已去神不从。","其余巨者庶免劫，肌理入石无初终。","山花分红极窈窕，幽草判绿何蒙茸。","含苞不虞神鬼泄，落实分遣猿猱供。","我知画笔不得到，只有显晦无春冬。","驱除极感造化力，早以魑魅投寒空。","阴崖点入势益陡，南北向背皆从峰。","根株偏能孕灵药，牙爪谁识非真龙。","我行十步即一憩，树亦接引如朋从。","理奇终恐化作石，转运始信非人工。"]},{"t":"晓泊当涂","f":"五言律诗","c":["晓色入深港，停桡问古原。","人稀杨柳密，村僻鹳鹅喧。","不雨思祈社，无年学灌园。","朝歌尔何意，隐隐度崇垣。"]},{"t":"登八卦城楼怀古","f":"七言律诗","c":["海客秋惊病眼苏，江城西上眺平芜。","频年芦荻生高垒，往日旌旗入小孤。","天险几曾供饮马，山形依旧绕飞乌。","遗文蛇鸟谁相识，落日征人按昔图。"]},{"t":"舒城九日赠黄大","f":"五言律诗","c":["少贱犹能役，亲衰不近名。","避人来九日，为客起新正。","土俗寒偏寿，天心雨亦晴。","无嗟村落酒，一醉感秋情。"]},{"t":"杂诗 其一","f":"五言律诗","c":["今人匪至愚，古人匪天亶。","忧思徒匆匆，胡为损餐饭。","君看西驰日，去者当复反。","后有万世来，谁云我生晚。"]},{"t":"杂诗 其二","f":"五言古诗","c":["昔余慕清华，未尝废奔走。","闻言京洛客，年命亦有偶。","一自罹风尘，栖栖笑生亩。","置身苦未遂，预恐成老丑。","落日穷巷中，流光照虚牖。","持编映檐隙，妻孥哂其后。","朝齑不盈餐，夕枕讵贴首。","苦觅后世名，其人骨先朽。"]},{"t":"自渒水入淮半日至颍口","f":"五言古诗","c":["渒水流不归，长淮极天静。","我行发舒六，十月至清颖。","颍尾清我心，颍歌行复警。","严霜岸头重，积势落颓井。","古树啼鸺鹠，闻声不知影。","稍稍上初月，戚戚聚浮梗。","旷野无人居，扬沙极千顷。","中原此开阖，寥廓少翳屏。","行当苦岁月，栖亩寡实颖。","星辰肃中宵，行客畏短景。","踟蹰冰雪意，兆始心已领。","百里不可休，客程同兽挺。"]},{"t":"自颍水入淮","f":"古风","c":["我为颍川谣，忽与颖尾别。","君歌月映清淮流，不识孤篷已飘雪。","长淮岸头村树斜，短棹系岸惊栖鸦。","可怜人鸟共凄绝，天水阔处难为家。","操舟者谁北风劲，十五吴姬寄身命。","风波到眼不识愁，妆罢只照长淮镜。"]},{"t":"渡淮","f":"七言古诗","c":["长淮千里何溯洄，远自桐柏之山来。","洪纤巨细络诸水，汇此四渎通八垓。","东南巨浸古所说，原野气尽岩峦回。","傍淮田下赋亦下，生计恃水无余财。","长年挐舟送行客，楚女击楫中流哀。","云浮三时蚌开合，水结五色龙胚胎。","阳嘘阴吸有至理，水上白昼层宫开。","要令幽险各有所，造物大矣何容猜。","全淮得失系吴楚，宵济万马曾衔枚。","王公设险古不废，硖石置守高崔嵬。","牛羊在野牧马散，淮水萧瑟山童峐。","下流河势苦相夺，二水若合坤舆颓。","支祈力屈匪至此，河伯好事同台骀。","至人视世本一辙，险绝不异坳堂杯。","朝帆开寒雨迷浦，莫雁戛水阴成堆。","好风明日送舟疾，可至禹庙倾尊罍。"]},{"t":"游醉翁亭","f":"古风","c":["一成坯，再成英，一再曲折山以名。","注川曰溪，注溪曰谷，溪行谷行水声复。","蓝舆背山始入山，水声已往何时还。","未登醉翁亭，先翻醉翁操，山禽飞还水禽噪。","言寻醉翁石，更诵醉翁文。","醉翁宾客不可见，山石欲雨溪生云。","咄哉文字亦有灵，能使此山此水无余情。","我观翁时值梅喜且惊，犹复夭矫屈曲如龙形。","醉翁琴，琴喑喑，乃知醉翁待我成古今。","我歌一篇翁赏心，滁山高绝滁水深。"]},{"t":"立春日","f":"五言律诗","c":["频悲寒序促，那复值兹晨。","人意怜迟日，吾生重早春。","川原看气始，草木辨根陈。","白发还多病，踟蹰强饭身。"]},{"t":"洪源谒祖墓四首 其一","f":"五言律诗","c":["五世还支子，全家问悯孙。","野花生墓阙，古柏及祠门。","朴塞吾宁忝，渊源系觉尊。","所亲欣絮语，灯火入前村。"]},{"t":"洪源谒祖墓四首 其二","f":"五言律诗","c":["白首吾宗叔，黄眉入室姑。","未嫌新礼简，记取旧名呼。","历寝书留几，开筵酒在壶。","为言居处僻，烧笋出山厨。"]},{"t":"洪源谒祖墓四首 其三","f":"五言律诗","c":["书堂三十楹，列坐尽横经。","朴学传家久，乡山照眼青。","劈池栽石笋，裂幔出风霆。","绝忆阴厓北，春浓霰亦零。"]},{"t":"洪源谒祖墓四首 其四","f":"五言律诗","c":["重来携幼弟，此别念衰亲。","山果纷相赠，溪茶采尚新。","封书因问叔，劝食尚依人。","倘复移家返，应知未厌贫。"]},{"t":"杂诗 其一","f":"五言古诗","c":["客有雍门琴，未逢钟期生。","不审托业卑，独欲操正声。","合乐而殊歌，哀音而激鸣。","一弹赏音稀，再鼓里耳惊。","持谢一世人，辛苦难自明。","琴声诚未谐，藉洗笛与筝。"]},{"t":"杂诗 其二","f":"五言古诗","c":["古贤乐箪瓢，昔圣廉一介。","信哉百世师，取与夙所戒。","清修既不饬，多藏以为快。","陈平节尤累，戴圣儒复败。","人慕庄周通，吾师伯夷隘。"]},{"t":"赠木兰院僧诵苕二首 其一","f":"七言绝句","c":["相逢同著软红尘，谁认前身与后身。","我信西来本无佛，茅庵还坐苦吟人。"]},{"t":"赠木兰院僧诵苕二首 其二","f":"七言绝句","c":["谋餐曾费写经钱，迟客犹留炊后烟。","一样扬州木兰院，山僧煮笋廿年前。"]},{"t":"楼上","f":"七言律诗","c":["楼上疏灯彻夜明，营前击柝断人行。","宵严都尉亲巡栅，岁歉村农罕入城。","岘首一书愁未报，淮南十月更孤征。","霜寒不是无衣苦，凄瑟难为负米情。"]},{"t":"段上舍达和《修竹吾庐图》","f":"古风","c":["我家城东南，数日过城北。","马家池头竹树幽，破晓来看雨中色。","我思移竹先移居，近乞数笋栽东隅。","待其干老笋复茁，影覆一室真吾庐。","君于此意亦三复，笔底森森绘寒玉。","夜阑题竹复赠君，惊笋出我墙东屋。"]},{"t":"瘦影疏香图","f":"七言律诗","c":["帘前露色垂空白，屋底镜光擦惨黑。","三更窗外发古梅，瘦步行来月华直。","寒雅窥人争一枝，却视人影何参差。","雏颜小妹愁不知，处姊十五应相思。"]},{"t":"送黄大景仁至都门四首 其一","f":"七言律诗","c":["弱冠心期誓始终，故人江夏有黄童。","数行书札来春半，一夕舟樯出雨中。","雀鼠几时仍共穴，马牛谁信不同风。","应怜楚越依都遍，更向燕台试转蓬。"]},{"t":"送黄大景仁至都门四首 其二","f":"七言律诗","c":["姑溪夜雨剪春蔬，归计频番说荷锄。","放眼关河斜日永，惊心岁月二毛初。","生涯未解营巢急，妻子都嗤涉世疏。","此日北堂应有梦，凝尘黯黯鬓慵梳。"]},{"t":"送黄大景仁至都门四首 其三","f":"七言律诗","c":["铅椠频年席未温，十年心迹几朱门。","难忘节物偏垂涕，有约乾坤不受恩。","涉世未妨颜更冷，依人何意舌犹存。","萧萧故业斜阳外，共尔无惭廉吏孙。"]},{"t":"送黄大景仁至都门四首 其四","f":"七言律诗","c":["踪迹平生苦未闲，我贫君病改朱颜。","料量绝业思传世，各有名山待闭关。","晓袂静看云气白，夜灯慵拂剑光斑。","偏惭楚客多乡思，依旧春风策蹇还。"]},{"t":"南村散赈图为山阳尉题","f":"七言古诗","c":["河流东来不可当，忆昨鱼鳖升君堂。","官卑方摄丞簿尉，天险欲合江淮黄。","河流决城已旬日，散赈遂呼尉官出。","尉官耳聋年六十，验票呼人百无失。","大者屋角狂狐奔，小者树底饥鹰蹲。","头颠颈缩三日饿，共盼赈粟来空村。","持瓢举釜复携斗，已见千人立沙阜。","黄衫小吏足不停，村后村前更招手。","深泥没髁无肩舆，尉来村北跨一驴。","行筹散尽整鞭去，不遣索米来豪胥。","淮阴太守知君绩，早晚台端奏贤迹。","君今所补非寸尺，不见遗黎活千百。"]},{"t":"道中作","f":"七言律诗","c":["上元县南逢野叟，势力渴走将何求？","呼余道上马应马，羡尔笠边牛戴牛。","禾枯浃旬向余语，欲到官衙请祈雨。","翁乎任尔秧种枯，县官祈雨怕减租。"]},{"t":"蓬生麻中行","f":"古风","c":["但种麻，莫种蓬，种麻蓬已生麻中。","移蓬根，植麻侧，蓬心飞扬麻性直。","君不见，蓬生麻中有张说，百年所争只一日。"]},{"t":"即事","f":"五言古诗","c":["去冬淮安荒，民死十七八。","天意未可知，水荒兼旱魃。","感兹财赋地，频复降兹罚。","抑闻物力侈，商贾更轻滑。","土木既已繁，多金建崇刹。","奢淫理召祸，谁复肯深察。","盛夏百草枯，炎炎肆诛杀。"]},{"t":"夜起","f":"五言古诗","c":["远随明月去，独望晓星来。","蟋蟀三两声，海棠花半开。","秋衫全湿露，团扇半粘苔。","户讶流萤出，窗惊电影回。","非因驰照远，谁复认池台。"]},{"t":"楼上倚声图","f":"古风","c":["夏居舫，秋居楼，月华只来楼上头。","吹琼箫，续羌笛，梧叶秋飘古墙隙。","梧飘一叶笛一声，声迟声疾已五更。","秋花如烟隔墙里，石上听歌人未起。"]},{"t":"道士家看菊","f":"七言律诗","c":["道人半岁不出门，种得阶前一畦菊。","菊枯望雨无消息，日致城西水三斛。","百钱买水宁忍饥，花开道士已典衣。","我笑琳宫狂道士，看菊朝饥还饮水。"]},{"t":"十月六日同朱大桂芳孙大星衍城南晚步","f":"七言古诗","c":["十日五日一出游，原上草木初辞秋。","惜哉岁歉寡欢思，且觅二子吟穷愁。","市中扰扰无百家，落日鼓已鸣官衙。","饥民入市竞挐攫，野店插竹凭拦遮。","故人住近宫墙左，破壁经时有烟火。","吏病无能索市租，客来聊复供山果。","芒鞋日晚踏市尘，城上月出光愁人。","斜阳欲没尚未没，照曜树顶栖鸟嗔。","城南城北荒途永，城里蓬蒿余百顷。","桧柏难寻隐士坛，辘轳已断仙人井。","前时一雨润麦田，短麦稍喜抽平阡。","已看黄口竭樵采，忍听白发谈丰年。","道旁一辈还相告，曰昨征西捷书到。","百斛襄船米禁开，征人失喜居人噪。","我今作客虽一方，百里尚得称吾乡。","眼中见此谁得忍，树赤无皮石无粉。"]},{"t":"自元符宫上大茅峰憩晓霞阁","f":"五言古诗","c":["申旦不复眠，视此崖上月。","初阳尚未升，了了见仙阙。","冥濛松树外，复见一星没。","楼北客尚眠，楼西窗已豁。","蓝舆顾不至，久待意郁勃。","二里抵一泉，流清鉴毛发。","延回积千转，磊磊出山骨。","原野何郁迂，阴云气飘忽。","层楼自孤迥，毁壁尚高揭。","原田间山麓，百复不居一。","岁歉民气怒，山行寡完褐。","犁锄复群聚，草树经㔉掘。","野雉不敢飞，穷搜入狐窟。","疲踪愿登阁，幽想已入樾。","曾言富仙酿，斟酌苦易竭。","亦感生计微，年荒未收秫。"]},{"t":"自句容至江宁半道欲游青龙山未果","f":"五言律诗","c":["鸣鸡声未断，一路续山禽。","古寺出层碧，当门转午阴。","霜林鞭影瘦，石凳烧痕侵。","客饭匆匆去，幽栖未及寻。"]},{"t":"大风登摄山顶望江","f":"七言律诗","c":["山僧出户惊狂客，绝顶立同山木植。","苍松冈南阁一层，飞鸟欲下人还登。","白云濛濛一招手，天风忽吹离立久。","雄心直挟海水飞，南望天门北京口。"]},{"t":"紫峰阁石龛作","f":"七言律诗","c":["几年扪壁壁忽崩，石顶裂穴藏枯僧。","穷冬移来暑复出，爱此云气时熏蒸。","幽崖无风日色断，贴屋惊看蛰虫满。","枯僧定后眼忽开，下视山空地轮转。"]},{"t":"客句容署中以县试不得出寄孙大","f":"七言律诗","c":["梦醒空自惜年华，法鼓声声报晚衙。","两度总惭巢幕燕，一春只看隔墙花。","窥灯鼠怯穿衣桁，绿壁虫惊落画叉。","我自怀人不能寐，高吟时复振窗纱。"]},{"t":"寄张绍南","f":"五言律诗","c":["只隔桥南北，离居未得同。","酒魂沉盏绿，春梦压灯红。","念尔孤生蒂，怜余独转蓬。","乡心与流水，日夕向川东。"]},{"t":"赵大怀玉招饮醉后却寄","f":"古风","c":["朝狂饮百觞，暮狂饮千钟。","恨客只说樊少翁，怪君何招盖次公。","立谈一语咸失欢，醉乡天地何能宽。","醒时颇知客颜色，兀兀一尊移向壁。","酒狂于我不可当，一月不出蓬蒿堂。","读书只欲究世务，放笔安肯为词章。","胸中之奇亦思吐，意欲上书丞相府。","直将心迹寄青云，不用头颅入黄土。"]},{"t":"独鹤行寄黄景仁","f":"古风","c":["独鹤亦不高，如人长七尺。","罗张网布不可以暗飞，悄然堕尔秋原之孤白。","幽蟾光短不得长，一星当天病眼黄。","鹤于此时何处翔？","不随雅头青，不随鸭头碧。","不随愁鸿南，不随悽燕北。","汝黑汝白不可知，汝南汝北我则思。","君不见羽毛如霜膝如铁，汝今虽远游，慎勿使霜毛摧、铁骨折。"]},{"t":"饥鹓行寄孙星衍","f":"古风","c":["饥鹓尔何来，闻自天上堕。","世人不知为奇祥，闻声而惊反惧祸。","何为牵汝头，缚汝脚，使汝乌不乌，鹊不鹊。","墙倾月明，庭低露凉。","秋虫食之，令人心伤。","徘徊不能行，我见惊是饥凤凰。","君不见，凤凰虽已饥，光彩自不藏。","犹吐五色云，高若百尺樯。","世人文章休目迷，我辨毛质皆山鸡，不然何以饥鹓苦饥汝苦肥？"]},{"t":"自嵊县至天台山行杂诗 其一","f":"五言古诗","c":["枫生北山上，叶落入西岭。","伤此东南风，愁看去来影。","萧条暮天气，凄瑟绝人境。","露草黄一坛，土花红半井。","伤禽既相戒，厩马行复警。","寥廓天地心，穷秋一深省。"]},{"t":"自嵊县至天台山行杂诗 其二","f":"五言古诗","c":["夜吟方倚树，晓梦已入竹。","风铃散疏声，悬灯照凄绿。","颇欣谢尘事，息仰在深谷。","迹感铩羽禽，狂惊失群鹿。","穷乡此留滞，乐岁苦踯躅。","岂念怀与安，徒成歌复哭。"]},{"t":"自嵊县至天台山行杂诗 其三","f":"五言古诗","c":["青溪多道士，华栋祀仙人。","绿屩封君达，酡颜贺季真。","林腰束云岫，谷口入风尘。","川绿疑成雨，岩红忽觉春。","开窗怪禽集，系槛野猿驯。","无由乞灵药，终此驻闲身。"]},{"t":"自嵊县至天台山行杂诗 其四","f":"五言古诗","c":["山禽呼水禽，栖息多在户。","夏虫语秋虫，寒久何忽暑。","川原既相间，凉燠各有主。","车马喧寂中，劳劳自尔汝。","征衣冒荆棘，客饭杂尘土。","曰发斑竹山，言寻白蘋浦。"]},{"t":"天台赤城歌寄孙大","f":"古风","c":["赤城黄海天下奇，我昔探奇入云海。","天台山高一万丈，结雾蒙云住仙宰。","奔车覆舟何不闲，数载岂复窥青山。","丈夫事业百无就，筋力苦瘁登临间。","山中之人薜萝绕，尘面看山亦徒扰。","奔猿立鹤噪岂休，笑我饥驱发蓬葆。","黄尘入骨体不轻，手扶赤藤上赤京。","崖穷壑转忽相失，侧耳已听鸣泉清。","尘寰下士禽子夏，五岳游期迫衰谢。","我留绿发不敢迟，急复料理居山资。","人生何为南北驰，忧患亦苦无穷时。","岩栖谷汲谁赏心，素抱幸有雍门琴。","不然云山苍苍万条路，更挂飞瓢觅君去。","吟肩拍处我欲狂，君亦寻君遂初赋。"]},{"t":"瓯江阻雨夜起望江心寺作","f":"七言绝句","c":["海潮初入雨纵横，帆落东瓯九斗城。","夜半题诗亦何意，荒鸡声里酹先生。"]},{"t":"清明后一日与孙大携酒饮王七秀才廷俞南圃归过县门忆亡友林嗣基作","f":"七言律诗","c":["劳劳身计本无涯，生倘多愁死亦佳。","阅世短于欹枕梦，招魂长入酒人怀。","琴书风卷知谁在，花月尊空与愿乖。","欲把闲踪比飞絮，年年开落县南街。"]},{"t":"夜行宿迁道中","f":"七言律诗","c":["荒原真厌马行迟，不定阴晴四月时。","破涧怒雷分雨势，断厓高树表风枝。","无家已绝经年梦，有约先悬出世思。","他日故巢相忆处，好寻芳草寄卷施。"]},{"t":"得孙大江宁书却寄","f":"七言律诗","c":["樱桃一树傍红墙，书到翻怜客异乡。","酒癖更沾衣袂湿，花疏时入枕函香。","删除好梦缘妨睡，检点闲身未肯狂。","我欲悟君先学道，携编三月坐匡床。"]},{"t":"代书寄汪大端光八十韵","f":"五言古诗","c":["百虑不失一，子才为世需。","六经甫通三，我识愧里儒。","才识工拙间，出处不可图。","子意乃不然，劝我入帝都。","为言予有亲，尚欲依菰芦。","子亲存我亡，一语伤藐孤。","负米十四年，娄空粟与刍。","子行燕赵归，勤作反哺乌。","我成吴越游，忽为失母雏。","我生惭世间，感子引作徒。","为倾橐中金，为计道上储。","六百里水程，十八日旱途。","历历夷险郊，孰宿孰可餔？","英英公卿中，孰谒孰则毋？","我足虽云劬，子口亦以瘏。","感子珍重心，临行野踟蹰。","譬若深谷风，幽草亦渐苏。","存亡心已伤，离别泪屡枯。","萋萋四月花，莽莽长河芜。","挈弟既惨悽，念友更咽呜。","相离第一程，梦子秦邮湖。","凉月忽抱肩，老鱼窥汀蒲。","东阿县西门，梦子又在吴。","俱为少年游，灯舫狂呼卢。","三梦宣武坊，斜日殷铜铺。","新知无一人，知子应念吾。","每梦必有泪，每泪必有书。","书皆千万言，纸恶字迹粗。","岂惟字迹粗，兼愧言辞纡。","长安识君人，谤誉亦复俱。","每苦立论严，憎子所服殊。","我不置一辩，归室始叹吁。","欲摘天半星，为子冠上珠。","欲剪湘中霞，为子身上襦。","天河濯五色，色异凡紫朱。","天衢曝众文，文匪常罗繻。","春月润子颜，秋露濯子肤。","日吐瑰丽辞，称此佩服都。","日陈琳球响，称此颜色姝。","留侯似妇人，曲逆美丈夫。","不闻史传讥，但觉流辈无。","尘冠弊履中，不必德义孚。","囚首垢面人，不必名实符。","虽然愿一言，少岁亦已徂。","二十颜尚髫，三十颔有须。","吾徒勤事业，弃置常所须。","要当惜心神，何必营衣裾。","急从良友箴，息此俗论诬。","明年登玉堂，三馆步复趋。","贻兹老成规，莫被轻薄愚。","我来人海中，戚戚意寡娱。","因缘识文人，千百量以车。","多文或为史，小智仅作胥。","行虽历方州，见乃守坐隅。","群獾出诗编，朱墨尽贡谀。","立语苦不工，已诩鲍谢逾。","我辈出直言，众目怒以盱。","谓我立论高，谓我制行迂。","一心苟无惭，兀兀任毁誉。","求子素识人，又各间一区。","非无杨生清，亦有黄子癯。","旬日乃握手，余皆掩蓬庐。","时时读子诗，消此嘅与歔。","子才信鹓鸾，我笔非于菟。","颇愧纷叠来，索诗若索逋。","我常思子言，气敛不敢舒。","逢子乃一发，笔禁口亦呼。","子书亦易作，字错墨屡涂。","前闻欲移家，急札驰邮奴。","煤车米石昂，讵可携妻孥。","况复堂上衰，行坐总欲扶。","岂任舟车劳，与此食粒粗。","诗储及瘦方，言皆悉锱铢。","讵不为子谋，使子鸟就笯。","子行试礼闱，先利矛与殳。","亦思贺万钱，不若储百壶。","倘或成同官，雅足见发纾。","拙效我亦收，令谟子先敷。","壮往庶有程，少习藉可除。","被酒一纵言，省札应豁如。"]},{"t":"八月二十日偕黄二暨舍弟饮天桥酒楼","f":"古风","c":["长安百万人，中有贱男子。","日挟卖赋钱，来游酒家市。","昨日送君回，今日约君来。","送君约君于此桥，长安酒人何寂寥。","酒人无多聚还喜，破帽尘颜挈吾弟。","摄衣上坐只三人，爽语寥寥落檐际。","君言内热需冷淘，我惯手冷应持螯。","闲无一事且沉醉，不然辜负青天高。","青天高高复飞雨，二十四棂风欲举。","飞蓬卷叶十里间，直视城南落惊羽。","浓云欲暗南郭门，斜日忽破千林昏。","阴晴万态斗秋景，醒醉一梦恬吟魂。","持千螯，挥百尊，不觉楼上空无人。","君归虽遥莫先走，万事要须落人后。","君不见，门前豪骑控双龙，笑我西行马如狗。"]},{"t":"被酒与吴生麟夜话","f":"七言绝句","c":["辽东道士应成鹤，阳羡书生莫化鹅。","尚有十年人海愿，却来吹笛共高歌。"]},{"t":"春江行赠汪大","f":"古风","c":["红阑干，影接天，一江春水阑干前。","阑干摇红水摇绿，波底阑文百回曲。","我共春江鱼，同饮春江潮。","潮声出入鲤鱼腹，水色荡漾吴侬瓢。","吴侬家，花满畦。","春风来，江北飞。","君门前，千树桃。","春雨落，江南飘。"]},{"t":"忆远行寄孙大","f":"古风","c":["波淼淼，星摇摇，约君不来暮已朝。","吴帆停，越车驾，约君不来春已夏。","春光九十静掩关，几年春闲君不闲。","层云万里宵征路，却恨君闲我难住。","十五已作同巢乌，南枝北枝名对呼。","十九更作寻源鱼，晓行虽远暮复俱。","东流水深，南枝有阴。","千里与万里，两心同一心。","朝心徘徊暮心怨，几日春魂自凌乱。","莫剪疏桃入户枝，春花开上横门扇。"]},{"t":"二月二十三日复与汪大上天桥饮醉歌","f":"古风","c":["著书不为千年计，直借陈编压奇气。","出门不逐万古愁，聊上高阁开吟眸。","天桥楼前一杯酒，昨日苦思今在手。","我能饮，君能留，三十莫抱二十忧。","识君二十年尚少，屈指十年君未老。","眉痕鬓影未减青，一色绿衫同似草。","盈楼饮客我独眠，未饮满掷青铜钱。","座中谁识两少年，江南江北无一田。","尊深酒熟莫更催，头上一云红覆杯。","休嫌饮尽众宾散，伴客时有春禽来。","城门楼上春阳满，一鸟啭春声缓缓。","城西山色影接天，极视惟愁目光短。","今日白昼饮，复胜清宵吟，百壶虽尽意不尽。","两客所喜皆同心，醉颜时红亦时白。","一市围观不相识，颇说近来无此客。"]},{"t":"为杨孝廉梦符题钱三维乔秦中画册即寄维乔","f":"古风","c":["何时得入函谷关，放笔即落终南山。","南山连绵画不竟，拔取一峰来入镜。","胸中有山即有楼，下笔有川兼得舟。","岂惟山水色不别，楼上客醉疑眠鸥。","醉颜昏昏忆孤在，逸客都为酒钱累。","剖胸欲入秦中云，洗眼仍须渭川水。","南山浮光，北山夕阳。","飞桥如云不能跨，怒蜺饮渚裁成梁。","林梢几尺天光足，怪石森森点寒绿。","此间应复置钱郎，四十癯颜尚如玉。","南高峰，北高峰，宦游今落名山中。","山川二月尤清旷，忆共钱郎饮湖上。","杨生思家静掩关，客帐梦好时时还。","吾曹须劝苦不闲，直当为画迢迢一溪之绿水，落落湖上之烟鬟。"]},{"t":"书从兄显祖画卷","f":"古风","c":["家有十步池，引水蓄百鱼。","室有三尺墙，种竹满四隅。","令其泉上有石，竹中通渠；","穿径之笋，不以入餐；","过桥之鱼，不使上竿。","鱼皆习主人，已忘江湖思。","修竹何娟娟，亦敛干霄姿。","主人不归归有时。","主人有一弟，倜傥素好奇。","曾就主人宿，爱此半亩之竹一亩池。","奇石落落，清流澌澌。","掩户十日卧，出关百里驰。","莲华峰头揽明月，挂尔溪边屋角之南枝。"]},{"t":"赵大至得孙大入关之信兼闻蒋表弟良卿欲入都城东酒徒无一人居里者感赋此首近简黄二杨三徐大","f":"古风","c":["一岁居里倾千壶，两年为客偿宿逋。","城东日日添酒垆，城西时时出酒徒。","城东酒楼一十六，城中少年出相续。","酒翁叹息酒妪愁，可惜少年皆远游。","少年谁最狂，雅数孙与黄。","就中短赵差有检，结束身手趋吟场。","东风吹春入酒楼，当时年少百不忧。","三更酣春楼上头，红烛光满楼前洲。","骑龙弄凤世不惊，只有酒家知姓名。","城东城西路回惑，只有酒家门径识。","酣嬉落魄非可常，一朝饯我束急装。","浓云浮江雨暗海，海风吹人颜面改。","离家岂独无酒筵，太息总无诸少年。","出门各历路万千，前后差喜皆游燕。","酒徒十辈五得官，余者不免谋饥寒。","孙郎苦恋里中乐，昨亦襆被辞江干。","新春忽梦晴溪曲，暗识溪南草应绿。","醉尉衙前碧月圆，蘋风乍转春流足。","花枝纵好酒纵醇，我识一城无酒人。","岂惟花发无酒人，兼恐减却楼头春。","春去春复来，春情忽然失。","朱颜变苍颜，黄金铸不得。","君不见，少年虽归非昔日，又有城东少年出。"]},{"t":"送崔二景俨南归读书并就婚","f":"古风","c":["忆昨同醉长安之酒楼，少年十辈君不浮。","忆昨同跨郊坰之骏马，偕游七人君最雅。","君才岂比凡少年，我意雅欲追前贤。","长安城中与君友，五度碧月联吟肩。","我交于世皆苍老，朱贾沦亡益悲悼。","吾曹缓急须托身，讵敢相轻此年少。","我感古人志行超，虽未绝交能寡交。","身今纵贱有殊禀，冀与一世回轻爂。","十年此志不暂忘，世人不知谓我狂。","乡闾益复盛嘲毁，并以余论加孙郎。","畏谗一室居疑蛰，昨者孙郎有书及。","我谋于众谢不敏，君独不辞乎燥湿。","亦知人生饶缓急，难尔少年尤独立。","朱门纨绮艳障天，独出英英矫余习。","吾侪快意得一朋，如入玉陛升金门。","急持一书报远人，谓此年少非常伦。","离风昨风吹原野，花叶纷披已成夏。","交君未久别念侵，独持一杯与论心。","酒楼花开三面阴，马蹄浮红五尺深。","燕秦十年游，近始抵乡土。","晏公祠外箫鼓喧，竞渡来看日端午。","离程关陇复数千，南瞻无家有墓田。","桑根草堂富经史，举半赠子穷雕镌。","识君不嫌迟，别君不嫌早。","读书溪南柳阴好，新妇窗前月痕皎。","人生聚散殊草草，君不见，百回相思令人老。"]},{"t":"将出都门留别黄二 其一","f":"七言绝句","c":["抛得白云溪畔宅，苦来燕市历风尘。","才人命薄如君少，贫过中年病却春。"]},{"t":"出都行涿州道中见芃麦遍野慨然有田庐之思因作田家诗二十首寄意并寄芮光照杨毓舒两布衣 其一","f":"五言律诗","c":["朝耕山上田，颇苦赤日酷。","雨气来北山，蜻蜓满空谷。","家遥糇粮具，释耒坐石屋。","日晚牵犊归，下山泥没足。"]},{"t":"出都行涿州道中见芃麦遍野慨然有田庐之思因作田家诗二十首寄意并寄芮光照杨毓舒两布衣 其二","f":"五言古诗","c":["山村十余家，古木自回互。","笋穿来东邻，果熟落北户。","居邻结姻娅，鸡犬互相顾。","出门望原田，高低百余步。","仲夏天气晴，凉风集高树。","茶瓜供过客，留话惬幽素。","日晚童樵归，问名均不误。"]},{"t":"出都行涿州道中见芃麦遍野慨然有田庐之思因作田家诗二十首寄意并寄芮光照杨毓舒两布衣 其三","f":"五言古诗","c":["穷乡寡文学，颇爱土俗淳。","茅檐八九家，五世相与邻。","儿童读书归，行处拾堕薪。","偶逢大父行，拱立识所亲。","日晚饷北皋，牵衣渡横津。","心忆朝诵书，沿途讽逡巡。"]},{"t":"出都行涿州道中见芃麦遍野慨然有田庐之思因作田家诗二十首寄意并寄芮光照杨毓舒两布衣 其四","f":"五言古诗","c":["门前隙地稀，屋后半亩绿。","桃李皆丰年，云兹佐嘉谷。","高曾手栽树，均作出檐木。","日午荫北窗，茅檐静堪托。","溪风一回荡，山果枝上熟。","童稚不识争，探怀已均足。"]},{"t":"出都行涿州道中见芃麦遍野慨然有田庐之思因作田家诗二十首寄意并寄芮光照杨毓舒两布衣 其五","f":"五言古诗","c":["力耕心志纯，外物不得动。","虽经百寒暑，寝息无一梦。","妻孥习辛勤，百世常与共。","秋成共欣慰，春至即播种。","年丰赛神毕，腊酒互相送。","尚嗔邻家翁，年衰腰足痛。"]},{"t":"出都行涿州道中见芃麦遍野慨然有田庐之思因作田家诗二十首寄意并寄芮光照杨毓舒两布衣 其六","f":"五言古诗","c":["村鸡一两声，持镰待天晓。","出门不知途，沿林警栖鸟。","宿雨零衣裳，原头刈新草。","牛饥我心急，况复犊难抱。","八口尝苦饥，饲牛尝苦饱。"]},{"t":"出都行涿州道中见芃麦遍野慨然有田庐之思因作田家诗二十首寄意并寄芮光照杨毓舒两布衣 其七","f":"五言律诗","c":["山泉奔曲涧，涧曲使鱼肥。","板屋临溪水，当窗白鹭飞。","高枝晒渔网，圆牖挂蓑衣。","莫讶轩窗陋，黄尘入户稀。"]},{"t":"出都行涿州道中见芃麦遍野慨然有田庐之思因作田家诗二十首寄意并寄芮光照杨毓舒两布衣 其八","f":"五言律诗","c":["朔风吹南山，黄叶满一屋。","扫之向墙隅，然薪一冬足。","田畴虽不广，常满瓮头粟。","闭户无所营，时还把书读。"]},{"t":"出都行涿州道中见芃麦遍野慨然有田庐之思因作田家诗二十首寄意并寄芮光照杨毓舒两布衣 其九","f":"五言古诗","c":["种松连高冈，云有先世坟。","一岁增尺土，巍然竟成原。","寒食飞纸钱，盈阡拜曾元。","但苦朴陋乡，讳字已不传。","日晚祭扫归，野花红如然。"]},{"t":"自河南入关所经皆秦汉旧迹车中无事因仿香山新乐府体率成十章 其一 荥阳城","f":"古风","c":["荥阳城，高百尺，因阜筑城如铁色。","汉王夜出城西门，荥阳以东属楚人。","惜哉一鹿抵死争，食肉不足思分羹。","当时若翁幸不烹，乃火纪信燔周生。","嗟嗟两烈士，殉主亦殉名。","我行天下历州七，奇险无若荥阳城。","君不见，荥阳城，值太平；","排百雉，无一兵。","司关午卧门掩扇，百战古城今下县。"]},{"t":"自河南入关所经皆秦汉旧迹车中无事因仿香山新乐府体率成十章 其二 尸乡置","f":"古风","c":["尸乡置，客欲愁，三十里进生王头。","海中山，波欲涌，五百人同死士垄。","有死士，无生王，王头上殿目尚光。","九重真龙为一哭，韩王楚王颜瑟缩。","腐儒造醢理不诬，王头乃复偿腐儒。","我来尸乡中，白日忽挂树，乡人说王尚如睹。","君不见，王爱士，士效忠，诚不若项王故人吕马童，手裂王体居奇功。"]},{"t":"自河南入关所经皆秦汉旧迹车中无事因仿香山新乐府体率成十章 其三 贾谊墓","f":"古风","c":["西京执戟郎，绿鬓忽已皓。","太宗爱老臣乃少，武皇爱少臣复老。","坐令人惜贾洛阳，怀奇亦不值武皇。","灌婴周勃哙伍耳，是老秃翁何足详。","长沙西来对宣室，汉皇才高殊自失。","固知尚鬼由楚人，因从楚来询鬼神。","鬼神之言亦陈戒，汉廷惟生识成败。","君不见，微吟贾生赋，车过洛阳界，坟荒无人碑已坏。","纷纷何况里中儿，我亦少年先下拜。"]},{"t":"自河南入关所经皆秦汉旧迹车中无事因仿香山新乐府体率成十章 其四 二崤山","f":"古风","c":["逼仄复逼仄，西经二崤山。","山溜冲作道，巨石横为关。","关门前，黑如许，西飘秦风东晋雨。","南陵北陵事迹陈，遑识夏后兼周文。","止忆晋五帅，秦三臣，为晋胜，为秦奔。","晋人虽墨衰，秦人亦素服。","向师茫茫恸秦穆，老臣此时无泪哭。","出山一里路渐平，巨石夹道愁纵横。","君不见，山凹不特炎暑酷，瞥有野鹰来攫肉。"]},{"t":"徐大书受浴牛图","f":"古风","c":["南沟水，流北沟。","水行苦无舟，幸有辕下牛。","羡君使牛如使舟，跨腹稳渡春塘流。","南沟水清，北沟水浊。","浊流须浴牛，水清留濯足。","螺千升，泥一斗。","尺鲤寸虾无不有，濯足流还入牛口。","君不见，春田之外官路高，百千万事如牛毛。","人饶千驷不能乐，君有一牛亦足豪。"]},{"t":"闻孙大二女皆殇书此慰之并促入都","f":"古风","c":["朝不见尔，暮不见尔。","不能得尔书，使我烦忧不能止。","朝知尔，枕一书。","暮知尔，入酒垆。","鸦飞鹊翻门索逋，盘盘广文居。","今岁殇两女，陨一奴。","缢魄复跳梁，掷此巨绠粗。","赫然三重门，常有十幅符，长人鬼伯利弱徒。","其余精魄强，睥睨孰敢如？","阳春倏然回，阴煞尽扫除。","丈人康强大母扶，行见妇归而将雏。","尔既久失，偶又苦贫，曷不远游负粟以奉亲？","长安辈流中，近复无尔比。","吾当属王三，为尔戒行李。"]},{"t":"投床下","f":"古风","c":["开国主，颜如婆婆形取嗤。","杨阿摩，投床顾欲拯舅氏，宫中反出奇男子。"]},{"t":"入牛口","f":"古风","c":["流星大如斛，流星大如斗，隋家天子下殿走。","君不见，郑家天子持羊干，夏家天子入牛口。"]},{"t":"起义兵","f":"古风","c":["唐高祖，起义兵。","何不学汤武，乃袭禅让名。"]},{"t":"与公诀","f":"古风","c":["杀建成，杀元吉，侯君集张亮，又复与生诀。","君不见，诛管蔡，族信布，上法周元公，下法汉高祖。"]},{"t":"房公谋","f":"古风","c":["房公谋，杜公断。","不数萧曹在西汉，英公卫公逾绛灌。","君不见，魏征妩媚谁可方，西京庶比张子房。"]},{"t":"三斗葱","f":"古风","c":["宁食三斗艾，不见屈突盖；","宁食三斗葱，不见屈突通。","屈突通，生勋第一死谥忠，只惜面缚来河东。"]},{"t":"天策府","f":"古风","c":["天策府，足文武。","右班徐李左房杜，一传已复作叛臣。","杜衍房遣爱，复有徐思文。"]},{"t":"文佳帝","f":"古风","c":["作尼能夺婿，作后先夺帝。","牝朝谁与开先声，文佳皇帝陈硕贞。"]},{"t":"求茧纸","f":"古风","c":["唐贞观，盛天子。","结习未忘何至此，乃向雉奴求茧纸。"]},{"t":"新丰酒","f":"古风","c":["长安百万宅，新丰一斗酒。","鸢肩火色人，可惜不得久。","君不见，褒公鄂公何足多，荐士转不如常何。"]},{"t":"十三人","f":"古风","c":["十三人，破万人。","倘不反，谁等伦。","豆子䴚，高鸡泊。","霸才不入凌烟阁，就中最惜王君廓。"]},{"t":"呼画师","f":"古风","c":["护儿儿作相，世南男作匠。","君不见，阎家兄弟更可嗤，为宰相，为大匠，为画师。"]},{"t":"凌烟阁","f":"古风","c":["凌烟阁，升功臣。","文学馆，升词臣。","二十四辈十八人，何须复图李嗣真。"]},{"t":"醉乡记","f":"古风","c":["一家著述谁最长，撰成世说记醉乡。","君不见，大儒纵自推文中，究不若，醉乡居士王无功。"]},{"t":"修本草","f":"古风","c":["《七略》详《素问》，《七录》升《本草》，吴公华公所搜讨。","唐兴百事皆修明，李姚史学贾孔经，医方亦校于志宁。"]},{"t":"远佞人","f":"古风","c":["魏征劝我远佞人，佞人谁，士及裴矩同封伦。","君不见，佞人毕竟不可离，两朝富贵封德彝。"]},{"t":"今接舆","f":"古风","c":["一友古许由，一作今接舆。","一师张留侯，一奉陶隐居。","丈人舟，居士屩，何似酒家南董好，大业贞观皆醉倒。"]},{"t":"扑此獠","f":"古风","c":["还笏起，血渍袍，帘中乃云扑此獠。","君不见，此獠扑杀罪亦当，仁师刘洎命合偿。"]},{"t":"十八人","f":"古风","c":["终身让路，不枉百步。","终身让畔，不失一段。","君家难弟兄亦真，絜身不预十八人。"]},{"t":"阿母子","f":"古风","c":["阿母子，作皇帝，裹儿亦欲缘此例。","君不见，太平安乐递擅朝，此时皇后躬南郊。"]},{"t":"矮子孝","f":"古风","c":["矮子劝食我必饱，矮子进药病必好。","君不见，母得此儿可不死，安得家家有矮子。"]},{"t":"安金藏","f":"七言古诗","c":["中兴唐祚说五王，论功不及安金藏。"]},{"t":"刘智远","f":"古风","c":["头颅一掷几不完，改名且复称儒冠。","改名谁？","刘智远。","后六百年当帝汉，姓名先已成左券。"]},{"t":"今董狐","f":"古风","c":["刘知几死那可诬，不畏生张说，只有今董狐。"]},{"t":"生张说","f":"古风","c":["才脱稿，已立碣，死姚崇算生张说。"]},{"t":"朝阳凤","f":"古风","c":["言路通，主德崇。","言路绝，国祚厄。","牝朝气运亦已终，一朝威凤鸣神龙。"]},{"t":"眼孔大","f":"古风","c":["是何胡儿眼孔大，宰相尚不足，只欲升御座。"]},{"t":"蜀当归","f":"古风","c":["叶法善，追魂碑，何似罗仙翁，能贻蜀当归。"]},{"t":"贤宰相","f":"古风","c":["贤宰相，大手笔，源张宋比汉三杰。","君不见，开元相，姚元崇。","天宝相，杨国忠。","一朝贤佞何不同，至今人惜唐玄宗。"]},{"t":"用康聓","f":"古风","c":["仆射弄獐，侍郎伏猎。","河湟使典，专主调燮。","此时康聓诚惶惶，日夜伫望官平章。"]},{"t":"檐铃声","f":"古风","c":["铃解语，嘲君王。","三郎郎当，郎当三郎。"]},{"t":"汾阳王","f":"古风","c":["为大将，为福将，终唐世，无与抗。","规模略具西平王，已与宰相多参商。"]},{"t":"中兴功","f":"古风","c":["中兴功，不可刊。","李郭为其易，张许为其难。"]},{"t":"骊山泉","f":"古风","c":["周骊山，烽火扬；","唐骊山，泉水香。","一水一火，国祚颠簸。","如何骊山，两值女祸。"]},{"t":"偃月堂","f":"古风","c":["堂偃月，阁格天。","一堂一阁构造完，金瓯天下已不全。"]},{"t":"兄与妹","f":"古风","c":["兄封卫，妹封虢。","一以谗，一以色。","一倾城，一倾国。"]},{"t":"禄山反","f":"古风","c":["禄山反，张公知。","朱泚逆，姜公知。","乌乎宰相有真识，两朝天子转溺惑。"]},{"t":"六等罪","f":"古风","c":["六等罪，案如铁。","张均张垍及希烈。","毕竟凝碧池，难恕王摩诘。","君不见，诗家可惜无鉴别，如何杜八哀，乃附郑三绝。"]},{"t":"于蔿于","f":"古风","c":["纵不识颜太师，不可不识元紫芝。","纵不识段忠烈，不可不识道州结。","君不见，君家讽颂何纡徐，十篇猗圩沮一曲，于蔿于。"]},{"t":"嗅靴鼻","f":"五言绝句","c":["一则嗅靴鼻，一不交一言。","若欲觇宰相，孰佞与孰贤。"]},{"t":"刘忠州","f":"古风","c":["言利臣，首宇文。","君不见，刘忠州，虽富国，已杀身，何况韦坚王鉷杨慎矜。"]},{"t":"盲宰相","f":"古风","c":["盲宰相，见地一何决，李元平当李希烈。"]},{"t":"某可相","f":"古风","c":["某可相，某可将，人方比伊周，自复拟葛亮。","苑中天子射兔忙，偏教母死不发丧。"]},{"t":"一丁字","f":"古风","c":["能识一丁字，胜挽弓十石。","君不见，三传宰相真寡识，二圣在河北，竟欲呼作贼。"]},{"t":"两拾遗","f":"古风","c":["至德中，大历中，两拾遗，真巨公。","李峤元稹作才子，岂比诗仙与诗史。"]},{"t":"阳道州","f":"古风","c":["阳道州，却诏书，臣州民短皆侏儒。","君不见，道州爱民有如此，直谏何妨忤天子。"]},{"t":"陛下误","f":"古风","c":["由畿尉，擢言路。","如何新进臣，敢说陛下误。","文章一代推中唐，柳韩元白各擅场，品端终属两侍郎。"]},{"t":"佑胆落","f":"古风","c":["居王屋，为处士。","居朝堂，为御史。","李佑雪夜成奇功，今日胆落朝堂中。"]},{"t":"送临贺","f":"古风","c":["送罪人，乃进职。","不负杨临贺，自不肯负国。"]},{"t":"少连笏","f":"古风","c":["秀实笏，击贼臣。","少连笏，击奸臣。","奸臣击纵不得死，不可谓非伟男子。"]},{"t":"雁塔名","f":"古风","c":["大雁塔，小雁塔，进士题名何杂沓。","李白杜甫盖代才，可向塔上题名来？"]},{"t":"呼陆九","f":"古风","c":["唐宰相资格可弗论，翰林学士须得人。","君不见，九重待若师举友，天子并闻呼陆九。"]},{"t":"十六子","f":"古风","c":["八关十六子，党祸自此始。","孤寒八百泪并流，此时毕竟思崖州。"]},{"t":"中兴相","f":"古风","c":["中兴宰相谁最优？","唐惟李文饶，汉则魏弱侯。"]},{"t":"甘露变","f":"古风","c":["用李训，用郑注，赤族祸，兆甘露。","君不见，当时宰臣最尸素，莫更追吟牡丹赋。"]},{"t":"仙韶院","f":"古风","c":["饭何所，木兰院。","钱何所，仙韶院。","一家将相三十年，少赖伊蒲餐，老给优伶钱。"]},{"t":"好羸马","f":"古风","c":["宁就荫，不试文。","好羸马，不入群。","会昌一品集，三唐进士皆不及。"]},{"t":"五色云","f":"古风","c":["文章好，门阀好。","天瑞五色云，人瑞郑仁表。","君家一事笑煞人，歇后郑五为相臣。"]},{"t":"中朝党","f":"古风","c":["河北贼，易易耳，中朝朋党哄不止。","党人祸结唐已亡，绝不关黄巢，亦不关朱梁。"]},{"t":"柳长官","f":"古风","c":["届一州，寿天子，柳泌公然为刺史。","君不见，丹方莫笑柳长官，郑注药要人心肝。"]},{"t":"孔吏部","f":"古风","c":["孔吏部，不乐居朝当有故。"]},{"t":"纥干雀","f":"古风","c":["离函秦，入京洛，纥干山雀何不乐？"]},{"t":"投浊流","f":"七言古诗","c":["唐家党祸今始休，清流均已投浊流。"]},{"t":"花林坊","f":"古风","c":["生何所，花树乡。","死何所，花林坊。","君不见，韦平章，诗名可继韩致光。"]},{"t":"马争栈","f":"古风","c":["二羊五马，扰及天下。","马争栈，羊脱缰。","羊已屠，马亦亡。"]},{"t":"唐天子","f":"七言古诗","c":["夜郎自大竟如此，洛州刺史唐天子。"]},{"t":"前进士","f":"古风","c":["侍中多，节使多。","君不见，头街何似梁高士，前进士名堪没世。"]},{"t":"罗秀才","f":"古风","c":["沈校书，杜主客，可怜唐进士，连翩尽臣贼。","君不见，罗家秀才未脱白，请兵诛梁一何力。"]},{"t":"修降表","f":"古风","c":["一隅蜀，何草草，五十年中两西讨。","君不见，文臣不合似李昊，生世偏工作降表。"]},{"t":"杀高郁","f":"古风","c":["唐天子，何太酷，一语居然杀高郁。"]},{"t":"耿先生","f":"古风","c":["前朝天子方服丹，后宫太后飞入山。","飞入山，从道士。","如何耿先生，亦复善生子。","君不见，长身玉貌殊可怜，卖药市上求青钱。"]},{"t":"杀潘福","f":"古风","c":["金陵城，宁作潘佑死，不作张洎生。","君不见，悔杀此人方出齿，明日牵机药随至。"]},{"t":"十国纪","f":"古风","c":["典午十六国，大半起西北。","唐余十国帝复王，十九皆起东南方。"]},{"t":"依样画","f":"古风","c":["陶学士，佐命功。","禅稿文，出袖中。","朱梁周郭皆禅让，君画葫芦亦依样。"]},{"t":"豹留皮","f":"古风","c":["人留名，豹留皮。","岂特王太师，兼有王凝妻。","男能断头女断臂，千载英英有生气。"]},{"t":"长乐老","f":"古风","c":["五代十数君，无一臻寿考。","九朝历事只一人，死同宣圣年，生作长乐老。"]},{"t":"王官谷","f":"古风","c":["蹂函秦，躏京洛，贼不敢入王官谷。","诗人一例悲沧桑，司空表圣韩致光。"]},{"t":"降王长","f":"古风","c":["唐李煜，蜀孟昶。","可惜覆国迟，不作降王长。"]},{"t":"泪洗面","f":"古风","c":["朝辞秦淮暮入汴，此间旦夕泪洗面。","泪洗面，何时干，不若叔实无心肝。"]},{"t":"铸错字","f":"古风","c":["虽去逼，已失势，四十三县铁，难铸一错字。"]},{"t":"读典坟","f":"古风","c":["生明时，读《典》《坟》，不然咏作何等人。"]},{"t":"致太平","f":"古风","c":["半部《论语》王业成，一篇《周礼》致太平，宋朝儒术何峥嵘。","君不见，学究来，宋阼开，语录布，倾宋阼。"]},{"t":"不晓天","f":"古风","c":["祥符中，宰相好。","歌柘枝，辄醉倒。","戴花吃酒须年少，不见宋家天不晓。"]},{"t":"女尧舜","f":"古风","c":["青苗除，免役除，女中尧舜谁得如。","君不见，内朝亦建宣仁号，仁政仁心法仁庙。"]},{"t":"求发白","f":"古风","c":["染髭须，染鬓发，染黑作白求宰执，染白作黑媚侧室。","君不见，今人古人何太远，宁作寇准无陆展。"]},{"t":"杨无敌","f":"古风","c":["李无双，杨无敌，两名将，光简策。","君不见，一既值卫青，一复逢王诜。","陈家谷，遂杀身，数奇亦似飞将军。"]},{"t":"得状元","f":"古风","c":["得状元，由手搏。","状元由手搏，尚胜种秘阁。"]},{"t":"尚书令","f":"古风","c":["尚书令，中书令，一张元，执国柄。","西师十万趋延安，此时空说有范韩。"]},{"t":"艮岳成","f":"古风","c":["艮岳成，大有益，北师攻城多炮石。"]},{"t":"误后世","f":"古风","c":["不可作，平章事，尤不可，作学士。","君不见，新法行，害一世；","新经行，害百世。"]},{"t":"党人碑","f":"古风","c":["碑磷磷，列党人。","碑首有君实，碑尾无安民。"]},{"t":"城门开","f":"古风","c":["言路开，城门塞，城门不塞言路塞。","靖康内禅亦可哀，城门言路已并开，二帝北狩何时回？"]},{"t":"冬青树","f":"古风","c":["花石网，北宋亡。","冬青一树，毕宋南渡。"]},{"t":"妇长舌","f":"古风","c":["臣粘罕，臣兀术，夫长脚，妇长舌。"]},{"t":"曲端旗","f":"古风","c":["十万师，败符离。","毕竟元帅符，不如曲端旗。"]},{"t":"和议成","f":"古风","c":["和议成，兵革偃，清凉居士时策蹇。"]},{"t":"梨花枪","f":"古风","c":["梨花枪，扰淮北。","可怜二十年，夫妇迭作贼。"]},{"t":"打六更","f":"五言古诗","c":["五更虽转六，国祚不可续。"]},{"t":"岳家军","f":"古风","c":["宁撼山，撼山易，撼岳家军难。","岳家军，易易耳，除大将，只小纸。"]},{"t":"贾平章","f":"古风","c":["贾平章，木棉庵，何如半闲堂。"]},{"t":"放白鸽","f":"古风","c":["放白鸽，放白鸽，引得白雁来，宫中尽臣妾。"]},{"t":"郑所南","f":"五言绝句","c":["画树不画根，画兰不画土。","谁说郑所南，不及王炎午。"]},{"t":"斗蟋蟀","f":"七言古诗","c":["荆襄一带胜败轻，正斗蟋蟀争输赢。"]}]};